function Get-P10ObservationWindowState {
  param([AllowNull()][object]$Observation,[AllowNull()][object]$Plan)
  $MinimumTotalHours=744
  $ExpectedPercents=@(1,5,20,50,100);$ExpectedSamples=@(50,100,250,500,1000);$ExpectedHours=@(24,48,72,120,168)
  $PlanValid=$null-ne$Plan-and[int]$Plan.minimum_nonoverlap_observation_hours-eq$MinimumTotalHours-and[bool]$Plan.windows_must_be_nonoverlapping-and[string]$Plan.window_started_at_field-ceq'window_started_at'-and[string]$Plan.window_ended_at_field-ceq'window_ended_at'-and[string]$Plan.duration_field-ceq'observed_hours'-and[double]$Plan.duration_tolerance_hours-eq0.01-and[string]$Plan.insufficient_total_observation_action-ceq'extend_current_gate'-and[bool]$Plan.stop_rules_remain_active_during_extension-and(@($Plan.minimum_adopted_runs)-join',')-ceq($ExpectedSamples-join',')-and(@($Plan.minimum_observation_hours)-join',')-ceq($ExpectedHours-join',')
  $Gates=if($null-ne$Observation){@($Observation.gates)}else{@()};$GateContractFailures=if($Gates.Count-eq5){0}else{1};$TimestampParseFailures=0;$TimestampOffsetFailures=0;$NonOverlapFailures=0;$DurationBindingFailures=0;$GateSatisfactionFailures=0;$ObservedTotalHours=0.0;$PreviousEnd=$null
  for($Index=0;$Index-lt$Gates.Count;$Index++){
    $Gate=$Gates[$Index]
    if($Index-ge5-or[int]$Gate.percent-ne$ExpectedPercents[$Index]-or[int]$Gate.required_adopted_runs-ne$ExpectedSamples[$Index]-or[double]$Gate.required_hours-ne$ExpectedHours[$Index]){$GateContractFailures++}
    if(-not[bool]$Gate.satisfied-or-not[bool]$Gate.all_risk_slices_observed-or[int]$Gate.observed_adopted_runs-lt[int]$Gate.required_adopted_runs-or[double]$Gate.observed_hours-lt[double]$Gate.required_hours-or-not[bool]$Gate.timer_restarted_on_transition){$GateSatisfactionFailures++}
    $StartText=[string]$Gate.window_started_at;$EndText=[string]$Gate.window_ended_at
    if($StartText-cnotmatch'(?:Z|[+-][0-9]{2}:[0-9]{2})$'-or$EndText-cnotmatch'(?:Z|[+-][0-9]{2}:[0-9]{2})$'){$TimestampOffsetFailures++}
    try{$Start=[DateTimeOffset]::Parse($StartText,[Globalization.CultureInfo]::InvariantCulture);$End=[DateTimeOffset]::Parse($EndText,[Globalization.CultureInfo]::InvariantCulture)}catch{$TimestampParseFailures++;continue}
    if($End-le$Start){$DurationBindingFailures++;continue}
    if($null-ne$PreviousEnd-and$Start-lt$PreviousEnd){$NonOverlapFailures++}
    $ElapsedHours=($End-$Start).TotalHours;$ObservedHours=[double]$Gate.observed_hours;$ObservedTotalHours+=$ObservedHours
    if([Math]::Abs($ElapsedHours-$ObservedHours)-gt0.01){$DurationBindingFailures++}
    $PreviousEnd=$End
  }
  $MinimumTotalFailure=if($ObservedTotalHours+0.01-lt$MinimumTotalHours){1}else{0}
  $Checks=[ordered]@{minimum_nonoverlap_observation_hours=$MinimumTotalHours;observed_nonoverlap_hours=[Math]::Round($ObservedTotalHours,3);plan_contract_failure_count=if($PlanValid){0}else{1};gate_contract_failure_count=$GateContractFailures;gate_satisfaction_failure_count=$GateSatisfactionFailures;timestamp_parse_failure_count=$TimestampParseFailures;timestamp_offset_failure_count=$TimestampOffsetFailures;nonoverlap_failure_count=$NonOverlapFailures;duration_binding_failure_count=$DurationBindingFailures;minimum_total_observation_failure_count=$MinimumTotalFailure}
  $Failure=[int]$Checks.plan_contract_failure_count+[int]$Checks.gate_contract_failure_count+[int]$Checks.gate_satisfaction_failure_count+[int]$Checks.timestamp_parse_failure_count+[int]$Checks.timestamp_offset_failure_count+[int]$Checks.nonoverlap_failure_count+[int]$Checks.duration_binding_failure_count+[int]$Checks.minimum_total_observation_failure_count
  return [ordered]@{passed=($Failure-eq0);checks=$Checks;minimum_nonoverlap_observation_hours=$MinimumTotalHours;observed_nonoverlap_hours=[Math]::Round($ObservedTotalHours,3)}
}

