function Get-P11000GateModeState {
  $RequiredModes=@('Preflight','WorkPreflight','WorksetVerify','Verify','Security','Evidence','RollbackVerify')
  if(-not(Test-Path -LiteralPath $script:GatePath -PathType Leaf)){return [ordered]@{passed=$false;missing_modes=$RequiredModes;failed_modes=@()}}
  $Results=@((Get-Content -LiteralPath $script:GatePath -Raw -Encoding UTF8|ConvertFrom-Json).results)
  $MissingModes=@($RequiredModes|Where-Object{$ModeName=$_;@($Results|Where-Object{[string]$_.check_id-ceq$ModeName}).Count-ne1})
  $FailedModes=@($RequiredModes|Where-Object{$ModeName=$_;$Rows=@($Results|Where-Object{[string]$_.check_id-ceq$ModeName});$Rows.Count-eq1-and[string]$Rows[0].status-cne'passed'})
  return [ordered]@{passed=($MissingModes.Count-eq0-and$FailedModes.Count-eq0);missing_modes=$MissingModes;failed_modes=$FailedModes}
}

function Get-P11000ChangedPaths {
  $Paths=@(& git -C $script:RepositoryRoot diff --name-only HEAD --)
  $Paths+=@(& git -C $script:RepositoryRoot ls-files --others --exclude-standard)
  $ReceiptPath=Join-Path $script:TaskEvidenceDirectory 'branch-receipt.json'
  if(Test-Path -LiteralPath $ReceiptPath -PathType Leaf){
    try{$Receipt=Get-Content -LiteralPath $ReceiptPath -Raw -Encoding UTF8|ConvertFrom-Json -ErrorAction Stop;$Base=[string]$Receipt.phase_base_sha;if($Base-cmatch'^[0-9a-f]{40}$'){& git -C $script:RepositoryRoot cat-file -e "$Base^{commit}" 2>$null;if($LASTEXITCODE-eq0){$Paths+=@(& git -C $script:RepositoryRoot diff --name-only $Base HEAD --)}}}catch{}
  }
  return @($Paths|Where-Object{$_}|ForEach-Object{$_.Replace('\','/')}|Sort-Object -Unique)
}

function Test-P11000PathAllowed {
  param([Parameter(Mandatory=$true)][string]$RelativePath)
  if($RelativePath-ceq'docs/execution/status/TASK-P11-000.json'){return $true}
  if($RelativePath-ceq'docs/execution/evidence/phase-11/phase-runtime-manifest.json'){return $true}
  return $RelativePath.StartsWith('docs/execution/evidence/phase-11/P11-000/',[StringComparison]::Ordinal)
}

function Get-P11000GitJsonRecord {
  param([Parameter(Mandatory=$true)][string]$Ref,[Parameter(Mandatory=$true)][string]$RelativePath)
  $PreviousErrorAction=$ErrorActionPreference;$ErrorActionPreference='Continue';try{$Output=@(& git -C $script:RepositoryRoot show "${Ref}:$RelativePath" 2>$null);$Exit=$LASTEXITCODE}finally{$ErrorActionPreference=$PreviousErrorAction}
  if($Exit-ne0){return [ordered]@{passed=$false;path=$RelativePath;raw='';sha256='';value=$null;error='git_object_missing'}}
  $Raw=$Output-join"`n";$Value=$null
  try{$Value=$Raw|ConvertFrom-Json -ErrorAction Stop}catch{return [ordered]@{passed=$false;path=$RelativePath;raw=$Raw;sha256='';value=$null;error='json_invalid'}}
  $Bytes=[Text.Encoding]::UTF8.GetBytes($Raw);$Hasher=[Security.Cryptography.SHA256]::Create()
  try{$Hash=([BitConverter]::ToString($Hasher.ComputeHash($Bytes))).Replace('-','').ToLowerInvariant()}finally{$Hasher.Dispose()}
  return [ordered]@{passed=$true;path=$RelativePath;raw=$Raw;sha256=$Hash;value=$Value;error=''}
}

function Get-P11000BranchState {
  param([ValidateSet('governance_preflight','rag_worktree')][string]$Stage='rag_worktree',[string]$ExpectedBaseOid='',[string]$ExpectedGovernanceOid='')
  $LocalRows=@(& git -C $script:RepositoryRoot for-each-ref '--format=%(objectname)%09%(refname)' refs/heads 2>$null);$LocalExit=$LASTEXITCODE
  $RemoteRows=@(& git -C $script:RepositoryRoot ls-remote --heads origin 2>$null);$RemoteExit=$LASTEXITCODE
  $Rows=@($LocalRows+$RemoteRows);$P11Rows=@();$Forbidden=@();$GovernanceOid=''
  foreach($Row in $Rows){
    $Parts=@([string]$Row-split'\s+');if($Parts.Count-lt2){continue};$Oid=[string]$Parts[0];$Ref=[string]$Parts[1]
    if($Ref-ceq'refs/heads/codex/release-c-governance'-and$Row-in$LocalRows){$GovernanceOid=$Oid}
    if($Ref-ceq'refs/heads/codex/phase-11-rag'){$P11Rows+=[ordered]@{oid=$Oid;ref=$Ref;scope=if($Row-in$LocalRows){'local'}else{'remote'}};continue}
    if($Ref-cmatch'^refs/heads/codex/(?:phase-11|phase-12)'){$Forbidden+=$Ref}
  }
  $Head=(@(& git -C $script:RepositoryRoot rev-parse HEAD 2>$null)-join'').Trim();$HeadExit=$LASTEXITCODE
  $Branch=(@(& git -C $script:RepositoryRoot branch --show-current 2>$null)-join'').Trim();$BranchExit=$LASTEXITCODE
  $Top=(@(& git -C $script:RepositoryRoot rev-parse --show-toplevel 2>$null)-join'').Trim();$TopExit=$LASTEXITCODE
  $TopNormalized=if($TopExit-eq0-and-not[string]::IsNullOrWhiteSpace($Top)){[IO.Path]::GetFullPath($Top).TrimEnd('\')}else{''}
  $Status=@(& git -C $script:RepositoryRoot status --porcelain=v1 2>$null);$StatusExit=$LASTEXITCODE
  $DirtyPaths=@($Status|ForEach-Object{if(([string]$_).Length-ge4){([string]$_).Substring(3).Replace('\','/')}else{[string]$_}})
  $UnexpectedDirty=@($DirtyPaths|Where-Object{-not(Test-P11000PathAllowed -RelativePath $_)})
  $Gitlinks=@(& git -C $script:RepositoryRoot ls-files --stage 2>$null|Where-Object{$_-cmatch'^160000\s'});$GitlinkExit=$LASTEXITCODE
  $CredentialLike=@(& git -C $script:RepositoryRoot ls-files --others --exclude-standard 2>$null|Where-Object{$_-cmatch'(^|/)(\.env($|\.)|id_rsa|id_ed25519|.*\.(pem|key|p12|pfx))$'});$CredentialExit=$LASTEXITCODE
  $NestedGit=@(Get-ChildItem -LiteralPath $script:RepositoryRoot -Recurse -Force -Filter .git -ErrorAction SilentlyContinue|Where-Object{$_.FullName-cne(Join-Path $script:RepositoryRoot '.git')})
  $BaseAncestor=$false;if($ExpectedBaseOid-cmatch'^[0-9a-f]{40}$'){& git -C $script:RepositoryRoot merge-base --is-ancestor $ExpectedBaseOid $Head 2>$null;$BaseAncestor=$LASTEXITCODE-eq0}
  $LocalP11=@($P11Rows|Where-Object{$_.scope-ceq'local'});$RemoteP11=@($P11Rows|Where-Object{$_.scope-ceq'remote'})
  $StageValid=if($Stage-ceq'governance_preflight'){
    $Branch-ceq'codex/release-c-governance'-and$Head-ceq$ExpectedGovernanceOid-and$LocalP11.Count+$RemoteP11.Count-eq0-and$UnexpectedDirty.Count-eq0
  }else{
    $Branch-ceq'codex/phase-11-rag'-and$TopNormalized-ceq'D:\GO_NOW-phase-11-rag'-and$Head-ceq$ExpectedBaseOid-and$LocalP11.Count-eq1-and[string]$LocalP11[0].oid-ceq$Head-and$RemoteP11.Count-eq0-and$BaseAncestor
  }
  return [ordered]@{
    passed=($StageValid-and$BaseAncestor-and$GovernanceOid-ceq$ExpectedGovernanceOid-and$Forbidden.Count-eq0-and$Gitlinks.Count+$CredentialLike.Count+$NestedGit.Count-eq0-and@($LocalExit,$RemoteExit,$HeadExit,$BranchExit,$TopExit,$StatusExit,$GitlinkExit,$CredentialExit|Where-Object{$_-ne0}).Count-eq0)
    stage=$Stage;stage_valid=$StageValid;query_failure_count=@($LocalExit,$RemoteExit,$HeadExit,$BranchExit,$TopExit,$StatusExit,$GitlinkExit,$CredentialExit|Where-Object{$_-ne0}).Count
    current_head_oid=$Head;current_branch=$Branch;worktree_path=$TopNormalized;worktree_dirty_count=$Status.Count;unexpected_dirty_count=$UnexpectedDirty.Count;base_ancestor=$BaseAncestor
    governance_ref_oid=$GovernanceOid;governance_ref_match=($GovernanceOid-ceq$ExpectedGovernanceOid);p11_ref_count=$P11Rows.Count;forbidden_specialist_branch_count=@($Forbidden|Sort-Object -Unique).Count
    forbidden_specialist_refs=@($Forbidden|Sort-Object -Unique);gitlink_count=$Gitlinks.Count;nested_git_count=$NestedGit.Count;credential_like_untracked_count=$CredentialLike.Count;production_write_count=0
  }
}

function Get-P11000TriggerState {
  param([AllowNull()][object]$Trigger,[AllowNull()][object]$Dependency,[DateTimeOffset]$Now=[DateTimeOffset]::Now)
  $RequiredRoles=@('Data','Engineering','Security');$SchemaErrors=0;$Cycle=[Guid]::Empty
  if($null-eq$Trigger-or[string]$Trigger.schema_version-cne'1.0'-or[string]$Trigger.task_id-cne'TASK-P11-000'-or[string]$Trigger.path-cne'phase11'-or-not[Guid]::TryParse([string]$Trigger.cycle_id,[ref]$Cycle)-or[string]$Trigger.evidence_sha256-cnotmatch'^[0-9a-f]{64}$'){$SchemaErrors++}
  $Measurement=if($null-ne$Trigger){$Trigger.measurement}else{$null};$WindowInvalid=0;$Start=[DateTimeOffset]::MinValue;$End=[DateTimeOffset]::MinValue
  try{$Start=[DateTimeOffset]::Parse([string]$Measurement.window_start);$End=[DateTimeOffset]::Parse([string]$Measurement.window_end);if($End-le$Start){$WindowInvalid++}}catch{$WindowInvalid++}
  $Denominator=if($null-ne$Measurement){[int]$Measurement.denominator}else{0};$Numerator=if($null-ne$Measurement){[int]$Measurement.stable_knowledge_gap_count}else{0};$Rate=if($Denominator-gt0){[double]$Numerator/[double]$Denominator}else{0.0};$RecordedRate=if($null-ne$Measurement){[double]$Measurement.rate}else{-1.0};$Threshold=if($null-ne$Measurement){[double]$Measurement.threshold}else{-1.0};$Confidence=if($null-ne$Measurement){$Measurement.confidence}else{$null}
  $MeasurementInvalid=if($null-eq$Measurement-or$Denominator-le0-or$Numerator-le0-or$Numerator-gt$Denominator-or[Math]::Abs($RecordedRate-$Rate)-gt0.000000001-or$Threshold-ne0.20-or-not[bool]$Measurement.threshold_calibrated-or$Rate-le$Threshold-or[string]$Measurement.timezone-cne'Asia/Shanghai'-or[string]$Measurement.classified_failure_sha256-cnotmatch'^[0-9a-f]{64}$'-or[bool]$Measurement.raw_user_data_included){1}else{0}
  $ConfidenceInvalid=if($null-eq$Confidence-or[double]$Confidence.level-le0-or[double]$Confidence.level-ge1-or[double]$Confidence.lower-le$Threshold-or[double]$Confidence.upper-gt1-or[double]$Confidence.lower-gt[double]$Confidence.upper-or$RecordedRate-lt[double]$Confidence.lower-or$RecordedRate-gt[double]$Confidence.upper){1}else{0}
  $Governance=if($null-ne$Trigger){$Trigger.governance}else{$null};$GovernanceInvalid=0
  if($null-eq$Governance-or[string]$Governance.adr.locator-cnotmatch'^immutable://'-or[string]$Governance.adr.sha256-cnotmatch'^[0-9a-f]{64}$'-or[string]$Governance.adr.status-cne'signed'){$GovernanceInvalid++}
  foreach($Name in @('license','privacy','residency','deletion')){$Item=if($null-ne$Governance){$Governance.$Name}else{$null};if($null-eq$Item-or[string]$Item.locator-cnotmatch'^immutable://'-or[string]$Item.sha256-cnotmatch'^[0-9a-f]{64}$'){$GovernanceInvalid++}}
  $Owner=if($null-ne$Trigger){$Trigger.owner_signature}else{$null};$OwnerInvalid=if($null-ne$Owner-and[string]$Owner.role-ceq'Product'-and-not[string]::IsNullOrWhiteSpace([string]$Owner.actor_id)-and[string]$Owner.decision-ceq'approved'-and[string]$Owner.candidate_sha-ceq[string]$Trigger.accepted_landing_sha-and[string]$Owner.cycle_id-ceq[string]$Trigger.cycle_id-and[string]$Owner.evidence_sha256-ceq[string]$Trigger.evidence_sha256){0}else{1}
  $Approvals=if($null-ne$Trigger){@($Trigger.approvals)}else{@()};$Roles=@($Approvals|ForEach-Object{[string]$_.role}|Sort-Object);$ApprovalInvalid=if($Approvals.Count-eq3-and($Roles-join',')-ceq(($RequiredRoles|Sort-Object)-join',')){0}else{1};$Expired=0
  foreach($Approval in $Approvals){$Unexpired=$false;try{$Unexpired=[DateTimeOffset]::Parse([string]$Approval.expires_at)-gt$Now}catch{};if(-not$Unexpired){$Expired++};if([string]::IsNullOrWhiteSpace([string]$Approval.actor_id)-or[string]$Approval.decision-cne'approved'-or[string]$Approval.candidate_sha-cne[string]$Trigger.accepted_landing_sha-or[string]$Approval.cycle_id-cne[string]$Trigger.cycle_id-or[string]$Approval.evidence_sha256-cne[string]$Trigger.evidence_sha256){$ApprovalInvalid++}}
  $Actors=@(([string]$Owner.actor_id)+@($Approvals|ForEach-Object{[string]$_.actor_id}));$ActorCollision=@($Actors|Where-Object{$_}|Group-Object|Where-Object{$_.Count-gt1}).Count
  $DependencyMismatch=if($null-ne$Dependency-and[bool]$Dependency.passed-and[string]$Trigger.accepted_landing_sha-ceq[string]$Dependency.accepted_landing_sha-and[string]$Trigger.cycle_id-ceq[string]$Dependency.cycle_id-and[string]$Trigger.path_selection_sha256-ceq[string]$Dependency.path_selection_sha256-and[string]$Trigger.release_b_sha256-ceq[string]$Dependency.release_b_sha256){0}else{1}
  $Checks=[ordered]@{schema_errors=$SchemaErrors;window_invalid_count=$WindowInvalid;measurement_invalid_count=$MeasurementInvalid;confidence_invalid_count=$ConfidenceInvalid;governance_evidence_invalid_count=$GovernanceInvalid;owner_signature_invalid_count=$OwnerInvalid;approval_invalid_count=$ApprovalInvalid;approval_expired_count=$Expired;actor_collision_count=$ActorCollision;dependency_binding_mismatch=$DependencyMismatch;denominator=$Denominator;stable_knowledge_gap_count=$Numerator;knowledge_gap_rate=$Rate;threshold=$Threshold;threshold_strictly_exceeded=($Rate-gt$Threshold);confidence_lower=if($null-ne$Confidence){[double]$Confidence.lower}else{-1};raw_user_data_included=if($null-ne$Measurement){[bool]$Measurement.raw_user_data_included}else{$true};production_write_count=0}
  $Passed=$SchemaErrors+$WindowInvalid+$MeasurementInvalid+$ConfidenceInvalid+$GovernanceInvalid+$OwnerInvalid+$ApprovalInvalid+$Expired+$ActorCollision+$DependencyMismatch-eq0
  return [ordered]@{passed=$Passed;checks=$Checks;trigger=$Trigger}
}

function Get-P11000DependencyState {
  param([DateTimeOffset]$Now=[DateTimeOffset]::Now)
  $GovernanceRef='refs/heads/codex/release-c-governance';$GovernanceOid=(@(& git -C $script:RepositoryRoot rev-parse $GovernanceRef 2>$null)-join'').Trim();$RefExit=$LASTEXITCODE
  $Paths=[ordered]@{selection='docs/execution/evidence/releases/REL-C-000/path-selection.json';trigger='docs/execution/evidence/releases/REL-C-000/rag-trigger-evidence.json';status='docs/execution/status/TASK-REL-C-000.json';gate='docs/execution/evidence/releases/REL-C-000/gate-results.json';release='docs/execution/evidence/releases/B.json'}
  $Records=[ordered]@{};foreach($Name in $Paths.Keys){$Records[$Name]=Get-P11000GitJsonRecord -Ref $GovernanceRef -RelativePath $Paths[$Name]}
  $Missing=@($Records.Keys|Where-Object{-not[bool]$Records[$_].passed});$Selection=$Records.selection.value;$Trigger=$Records.trigger.value;$Status=$Records.status.value;$Gate=$Records.gate.value;$Release=$Records.release.value
  $GateResults=if($null-ne$Gate){@($Gate.results)}else{@()};$RequiredModes=@('Preflight','WorkPreflight','WorksetVerify','Verify','Security','Evidence','RollbackVerify');$GateSetInvalid=@($RequiredModes|Where-Object{$Name=$_;$Rows=@($GateResults|Where-Object{[string]$_.check_id-ceq$Name});$Rows.Count-ne1-or[string]$Rows[0].status-cne'passed'}).Count
  $SelectionDependency=[pscustomobject]@{passed=$true;accepted_landing_sha=if($null-ne$Selection){[string]$Selection.accepted_landing_sha}else{''};evidence_sha256=if($null-ne$Selection){[string]$Selection.evidence_sha256}else{''};checks=[pscustomobject]@{prior_cycle_record_count=0}}
  $SelectionBranch=[pscustomobject]@{query_failure_count=0;specialist_branch_count=0;current_branch='codex/release-c-governance';governance_ref_oid=$GovernanceOid;current_head_oid=$GovernanceOid}
  $SelectionState=Get-RelC000SelectionState -Selection $Selection -Dependency $SelectionDependency -BranchState $SelectionBranch -Now $Now
  $Phase11Alternatives=if($null-ne$Selection){@($Selection.alternatives|Where-Object{[string]$_.path-ceq'phase11'})}else{@()};$Phase11EvidenceBound=$Phase11Alternatives.Count-eq1-and[string]$Phase11Alternatives[0].evidence_sha256-ceq[string]$Records.trigger.sha256
  $Accepted=if($null-ne$Release){[string]$Release.accepted_landing_sha}else{''};$StatusValid=$null-ne$Status-and[string]$Status.task_id-ceq'TASK-REL-C-000'-and[string]$Status.status-ceq'accepted'-and[bool]$Status.reviewer_independent-and[string]$Status.head_oid-ceq$GovernanceOid-and[string]$Status.evidence_sha256-ceq[string]$Records.gate.sha256
  $ReleaseValid=$null-ne$Release-and[bool]$Release.accepted-and[string]$Release.release_status-ceq'accepted'-and[string]$Release.stable_observation_status-ceq'passed'-and$Accepted-cmatch'^[0-9a-f]{40}$'-and[string]$Release.source_integration_sha-ceq$Accepted
  $SelectionValid=[bool]$SelectionState.passed-and[string]$Selection.path-ceq'phase11'-and[string]$Selection.accepted_landing_sha-ceq$Accepted-and[string]$Selection.cas_receipt.new_sha-ceq$GovernanceOid-and$Phase11EvidenceBound
  $TriggerBinding=$null-ne$Trigger-and[string]$Trigger.cycle_id-ceq[string]$Selection.cycle_id-and[string]$Trigger.accepted_landing_sha-ceq$Accepted-and[string]$Trigger.path_selection_sha256-ceq[string]$Records.selection.sha256-and[string]$Trigger.release_b_sha256-ceq[string]$Records.release.sha256
  $Checks=[ordered]@{dependency_failures=0;missing_input_count=$Missing.Count;governance_ref_query_exit_code=$RefExit;gate_set_invalid_count=$GateSetInvalid;rel_c_status_valid=$StatusValid;release_b_accepted_and_stable=$ReleaseValid;path_selection_valid=$SelectionValid;phase11_alternative_evidence_hash_match=$Phase11EvidenceBound;trigger_input_binding_valid=$TriggerBinding;path='phase11';cycle_id=if($null-ne$Selection){[string]$Selection.cycle_id}else{''};accepted_landing_sha=$Accepted;governance_head_oid=$GovernanceOid;production_write_count=0}
  $Passed=$Missing.Count+$RefExit+$GateSetInvalid-eq0-and$StatusValid-and$ReleaseValid-and$SelectionValid-and$TriggerBinding
  if(-not$Passed){$Checks.dependency_failures=1}
  return [ordered]@{passed=$Passed;checks=$Checks;accepted_landing_sha=$Accepted;governance_head_oid=$GovernanceOid;cycle_id=if($null-ne$Selection){[string]$Selection.cycle_id}else{''};path_selection_sha256=[string]$Records.selection.sha256;release_b_sha256=[string]$Records.release.sha256;trigger_sha256=[string]$Records.trigger.sha256;selection=$Selection;trigger=$Trigger;status_sha256=[string]$Records.status.sha256;gate_sha256=[string]$Records.gate.sha256}
}

function Test-P11AtomicTask {
  param([Parameter(Mandatory=$true)][string]$TaskIdValue)
  return $TaskIdValue-cmatch'^TASK-P11-(?:00[1-9]|010)$'
}

