function Get-P11AtomicDependencyAggregateState {
  param([Parameter(Mandatory=$true)][object]$Definition,[AllowNull()][object]$Manifest,[Parameter(Mandatory=$true)][Collections.IDictionary]$PredecessorStates,[string]$ExpectedCatalogSha='',[string]$ExpectedPlanSha='')
  $ManifestValid=$null-ne$Manifest-and[string]$Manifest.task_id-ceq'TASK-P11-000'-and[string]$Manifest.phase-ceq'Phase 11'-and[string]$Manifest.execution_mode-ceq'formal_adopted'-and[string]$Manifest.phase_base_oid-cmatch'^[0-9a-f]{40}$'-and[string]$Manifest.formal_phase_base_oid-ceq[string]$Manifest.phase_base_oid-and[int]$Manifest.prior_phase_regression_failures+[int]$Manifest.not_run+[int]$Manifest.future_oid_literal_count+[int]$Manifest.base_drift+[int]$Manifest.source_hash_drift-eq0
  if($ManifestValid-and-not[string]::IsNullOrWhiteSpace($ExpectedCatalogSha)){$ManifestValid=[string]$Manifest.catalog_sha256-ceq$ExpectedCatalogSha}
  if($ManifestValid-and-not[string]::IsNullOrWhiteSpace($ExpectedPlanSha)){$ManifestValid=[string]$Manifest.plan_sha256-ceq$ExpectedPlanSha}
  $Missing=@($Definition.prerequisites|Where-Object{-not$PredecessorStates.Contains($_)});$Invalid=@();foreach($Id in $Definition.prerequisites){if($PredecessorStates.Contains($Id)){if(-not[bool]$PredecessorStates[$Id].passed-or-not[bool]$PredecessorStates[$Id].accepted){$Invalid+=$Id}}}
  $Checks=[ordered]@{manifest_valid=$ManifestValid;predecessor_count=@($Definition.prerequisites).Count;missing_predecessor_count=$Missing.Count;invalid_predecessor_count=$Invalid.Count;accepted_predecessor_count=@($Definition.prerequisites|Where-Object{$PredecessorStates.Contains($_)-and[bool]$PredecessorStates[$_].accepted}).Count;production_write_count=0}
  return [ordered]@{passed=($ManifestValid-and$Missing.Count+$Invalid.Count-eq0);checks=$Checks;manifest=$Manifest;predecessor_states=$PredecessorStates}
}

function Get-P11AtomicDependencyState {
  param([Parameter(Mandatory=$true)][object]$Definition)
  $Head=(@(& git -C $script:RepositoryRoot rev-parse HEAD 2>$null)-join'').Trim();$HeadExit=$LASTEXITCODE;$ManifestRecord=Get-P11000GitJsonRecord -Ref HEAD -RelativePath 'docs/execution/evidence/phase-11/phase-runtime-manifest.json';$States=[ordered]@{}
  foreach($Prerequisite in $Definition.prerequisites){$Suffix=$Prerequisite.Substring(5);$StatusRecord=Get-P11000GitJsonRecord -Ref HEAD -RelativePath "docs/execution/status/$Prerequisite.json";$ArtifactRecord=Get-P11000GitJsonRecord -Ref HEAD -RelativePath "docs/execution/evidence/phase-11/$Suffix/artifact-hashes.json";$GateRecord=Get-P11000GitJsonRecord -Ref HEAD -RelativePath "docs/execution/evidence/phase-11/$Suffix/gate-results.json";$Status=$StatusRecord.value;$Artifact=$ArtifactRecord.value;$Gate=$GateRecord.value;$StatusAncestor=$false;$ArtifactAncestor=$false;if($null-ne$Status-and[string]$Status.head_oid-cmatch'^[0-9a-f]{40}$'){& git -C $script:RepositoryRoot merge-base --is-ancestor ([string]$Status.head_oid) $Head 2>$null;$StatusAncestor=$LASTEXITCODE-eq0};if($null-ne$Artifact-and[string]$Artifact.head_oid-cmatch'^[0-9a-f]{40}$'){& git -C $script:RepositoryRoot merge-base --is-ancestor ([string]$Artifact.head_oid) $Head 2>$null;$ArtifactAncestor=$LASTEXITCODE-eq0};$Modes=if($Prerequisite-ceq'TASK-P11-000'){@('Preflight','WorkPreflight','WorksetVerify','Verify','Security','Evidence','RollbackVerify')}elseif($Prerequisite-ceq'TASK-P11-089'){@((Get-P11089Definition).modes)}elseif($Prerequisite-ceq'TASK-P11-990'){@((Get-P11990Definition).modes)}else{@((Get-P11AtomicDefinition -TaskIdValue $Prerequisite).modes)};$Rows=if($null-ne$Gate){@($Gate.results)}else{@()};$GateInvalid=@($Modes|Where-Object{$Name=$_;$Found=@($Rows|Where-Object{[string]$_.check_id-ceq$Name});$Found.Count-ne1-or[string]$Found[0].status-cne'passed'}).Count;$StatusValid=$null-ne$Status-and[string]$Status.task_id-ceq$Prerequisite-and[string]$Status.status-ceq'accepted'-and[bool]$Status.reviewer_independent-and$StatusAncestor-and[string]$Status.evidence_sha256-ceq[string]$GateRecord.sha256;$ArtifactValid=$null-ne$Artifact-and[string]$Artifact.task_id-ceq$Prerequisite-and$ArtifactAncestor-and[int]$Artifact.production_write_count-eq0-and@($Artifact.artifacts).Count-gt0;$Present=@($StatusRecord,$ArtifactRecord,$GateRecord|Where-Object{[bool]$_.passed}).Count;$States[$Prerequisite]=[ordered]@{present_count=$Present;accepted=$StatusValid;passed=($Present-eq3-and$StatusValid-and$ArtifactValid-and$GateInvalid-eq0);status_head_oid=if($null-ne$Status){[string]$Status.head_oid}else{''};status_head_ancestor=$StatusAncestor;artifact_head_ancestor=$ArtifactAncestor;gate_invalid_count=$GateInvalid;status_sha256=[string]$StatusRecord.sha256;artifact_sha256=[string]$ArtifactRecord.sha256;gate_sha256=[string]$GateRecord.sha256}}
  $PlanSha=Get-Sha256 -LiteralPath (Join-Path $script:RepositoryRoot 'execplan.md');$Aggregate=Get-P11AtomicDependencyAggregateState -Definition $Definition -Manifest $ManifestRecord.value -PredecessorStates $States -ExpectedCatalogSha $script:CatalogSha256 -ExpectedPlanSha $PlanSha;$Aggregate.checks['head_query_exit_code']=$HeadExit;$Aggregate.checks['manifest_record_valid']=[bool]$ManifestRecord.passed;if($HeadExit-ne0-or-not[bool]$ManifestRecord.passed){$Aggregate['passed']=$false};$Aggregate['head_oid']=$Head;return $Aggregate
}

function Get-P11AtomicChangedPaths {
  $Paths=@(& git -C $script:RepositoryRoot diff --name-only HEAD --);$Paths+=@(& git -C $script:RepositoryRoot ls-files --others --exclude-standard)
  return @($Paths|Where-Object{$_}|ForEach-Object{$_.Replace('\','/')}|Sort-Object -Unique)
}

function Test-P11AtomicPathAllowed {
  param([Parameter(Mandatory=$true)][object]$Definition,[Parameter(Mandatory=$true)][string]$RelativePath)
  if($RelativePath-in@($Definition.files)){return $true};if($RelativePath-ceq"docs/execution/status/$($Definition.task_id).json"){return $true};if($RelativePath.StartsWith("docs/execution/evidence/phase-11/$($Definition.task_id.Substring(5))/",[StringComparison]::Ordinal)){return $true}
  foreach($Directory in @($Definition.directories)){$Prefix=[string]$Directory.path;if($RelativePath.StartsWith($Prefix,[StringComparison]::Ordinal)){$Name=$RelativePath.Substring($Prefix.Length);return -not$Name.Contains('/')-and$Name-cmatch[string]$Directory.name_regex}}
  return $false
}

function Get-P11AtomicBranchState {
  param([Parameter(Mandatory=$true)][object]$Definition,[Parameter(Mandatory=$true)][object]$Dependency)
  $Head=(@(& git -C $script:RepositoryRoot rev-parse HEAD 2>$null)-join'').Trim();$HeadExit=$LASTEXITCODE;$Branch=(@(& git -C $script:RepositoryRoot branch --show-current 2>$null)-join'').Trim();$BranchExit=$LASTEXITCODE;$Top=(@(& git -C $script:RepositoryRoot rev-parse --show-toplevel 2>$null)-join'').Trim();$TopExit=$LASTEXITCODE;$TopNormalized=if($Top){[IO.Path]::GetFullPath($Top).TrimEnd('\')}else{''};$LocalP11=@(& git -C $script:RepositoryRoot for-each-ref '--format=%(objectname)%09%(refname)' refs/heads/codex/phase-11-rag 2>$null);$LocalExit=$LASTEXITCODE;$Remote=@(& git -C $script:RepositoryRoot ls-remote --heads origin 'refs/heads/codex/phase-11*' 'refs/heads/codex/phase-12*' 2>$null);$RemoteExit=$LASTEXITCODE;$UnexpectedRemote=@($Remote|Where-Object{$_-cmatch'refs/heads/codex/phase-12'});$Paths=@(Get-P11AtomicChangedPaths);$Unexpected=@($Paths|Where-Object{-not(Test-P11AtomicPathAllowed -Definition $Definition -RelativePath $_)});$Base=[string]$Dependency.manifest.phase_base_oid;$BaseAncestor=$false;if($Base-cmatch'^[0-9a-f]{40}$'){& git -C $script:RepositoryRoot merge-base --is-ancestor $Base $Head 2>$null;$BaseAncestor=$LASTEXITCODE-eq0};$LocalValid=$LocalP11.Count-eq1-and([string]$LocalP11[0]-split'\s+')[0]-ceq$Head
