function Get-P11AtomicMissingDirectoryTargetCount {
  param([Parameter(Mandatory=$true)][object]$Definition)
  $Missing=0;foreach($Directory in @($Definition.directories)){$Root=Join-Path $script:RepositoryRoot ([string]$Directory.path);$Files=if(Test-Path -LiteralPath $Root -PathType Container){@(Get-ChildItem -LiteralPath $Root -File|Where-Object{$_.Name-cmatch[string]$Directory.name_regex})}else{@()};if($Files.Count-eq0){$Missing++}}
