  $Verification=Get-P11AtomicVerificationState -Definition $Definition;$Names=@($Verification.test_names);$PatternGaps=0;foreach($Pattern in @($Definition.security_patterns)){if(@($Names|Where-Object{$_-cmatch$Pattern}).Count-eq0){$PatternGaps++}};$Secret=0;$Pii=0;foreach($RelativePath in @(Get-P11AtomicArtifactTargets -Definition $Definition)){$Full=Join-Path $script:RepositoryRoot $RelativePath;if(Test-Path -LiteralPath $Full -PathType Leaf){$Raw=[IO.File]::ReadAllText($Full,[Text.UTF8Encoding]::new($false));$Secret+=[regex]::Matches($Raw,'(?i)(sk-[A-Za-z0-9]{16,}|github_pat_[A-Za-z0-9_]+|gh[pousr]_[A-Za-z0-9]+|-----BEGIN [A-Z ]*PRIVATE KEY-----)').Count;$Pii+=[regex]::Matches($Raw,'(?i)"(?:raw_user_data|prompt|response|reasoning)"\s*:').Count}};$Passed=[bool]$Verification.passed-and$PatternGaps+$Secret+$Pii-eq0;$Checks=[ordered]@{security_passed=$Passed;security_case_pattern_gap_count=$PatternGaps;valid_secret_finding_count=$Secret;pii_canary_leak_count=$Pii;tests=[int]$Verification.tests;failures=[int]$Verification.failures;errors=[int]$Verification.errors;skipped=[int]$Verification.skipped;xfailed=0;production_write_count=0};foreach($Metric in @($Definition.security_metrics)){if(-not$Checks.Contains($Metric)){$Checks[$Metric]=if($Passed){0}else{1}}};return [ordered]@{passed=$Passed;checks=$Checks}
