  if($null-eq$Value){return 0};$Sum=0;if($Value-is[Collections.IDictionary]){foreach($Key in $Value.Keys){if([string]$Key-in$Names-and$Value[$Key]-isnot[Collections.IEnumerable]){$Sum+=[int]$Value[$Key]};$Sum+=Get-P11990NamedMetricSum -Value $Value[$Key] -Names $Names};return $Sum};if($Value-is[Management.Automation.PSCustomObject]){foreach($Property in $Value.PSObject.Properties){if($Property.Name-in$Names-and$Property.Value-isnot[Collections.IEnumerable]){$Sum+=[int]$Property.Value};$Sum+=Get-P11990NamedMetricSum -Value $Property.Value -Names $Names};return $Sum};if($Value-is[Collections.IEnumerable]-and$Value-isnot[string]){foreach($Item in $Value){$Sum+=Get-P11990NamedMetricSum -Value $Item -Names $Names}};return $Sum
}

