  $Required=@('docs/execution/evidence/phase-11/knowledge-transfer.md','docs/execution/evidence/phase-11/P11-089/handoff-verification.json','docs/architecture/threat-model/phase-11-review.json','docs/execution/evidence/phase-11/artifact-manifest.premerge.json','docs/execution/evidence/phase-11/P11-089/gate-results.json','docs/execution/evidence/phase-11/P11-990/regression-summary.json');$Missing=@($Required|Where-Object{-not(Test-Path -LiteralPath (Join-Path $script:RepositoryRoot $_)-PathType Leaf)});if($Missing.Count-ne0){return [ordered]@{passed=$false;missing_count=$Missing.Count;kt_sections=0;hardest_item_count=-1;applicable_ct_failure_count=13;unresolved_local_blocker_count=1}}
  $Kt=Get-Content -LiteralPath (Join-Path $script:RepositoryRoot $Required[0])-Raw -Encoding UTF8;$Handoff=Get-Content -LiteralPath (Join-Path $script:RepositoryRoot $Required[1])-Raw -Encoding UTF8|ConvertFrom-Json;$Threat=Get-Content -LiteralPath (Join-Path $script:RepositoryRoot $Required[2])-Raw -Encoding UTF8|ConvertFrom-Json;$Manifest=Get-Content -LiteralPath (Join-Path $script:RepositoryRoot $Required[3])-Raw -Encoding UTF8|ConvertFrom-Json;$Gate=Get-Content -LiteralPath (Join-Path $script:RepositoryRoot $Required[4])-Raw -Encoding UTF8|ConvertFrom-Json;$Regression=Get-Content -LiteralPath (Join-Path $script:RepositoryRoot $Required[5])-Raw -Encoding UTF8|ConvertFrom-Json;$Blockers=Get-P11990LocalBlockerState;$Review=$Manifest.document_review;$Sections=@([regex]::Matches($Kt,'(?m)^##\s+')).Count;$Hardest=[regex]::Match($Kt,'(?m)^hardest_item_count:\s*([0-3])$');$DocReview=$null-ne$Review-and[string]$Review.status-ceq'local_verified'-and[bool]$Review.reviewer_is_implementer-and[string]$Review.independent_review_status-ceq'pending_external';$HandoffValid=[bool]$Handoff.handoff_journey_passed-and[bool]$Handoff.reviewer_is_implementer-and[string]$Handoff.independent_review_status-ceq'pending_external'-and[int]$Handoff.nonzero_exit_count+[int]$Handoff.production_write_count-eq0;$ThreatValid=[string]$Threat.architecture_model_sha256-ceq'644ab9f5ad04a65383bb34b6628b49472d9f68b50fa3681aa46671f59794c3a6'-and[string]$Threat.security_owner-ceq'Security'-and[bool]$Threat.reviewer_is_implementer-and[string]$Threat.independent_review_status-ceq'pending_external';$P11089Documentation=@($Gate.results|Where-Object{[string]$_.check_id-ceq'Documentation'-and[string]$_.status-ceq'passed'}).Count-eq1;$RegressionFailures=[int]$Regression.checks.failed+[int]$Regression.checks.not_run+[int]$Regression.checks.skipped+[int]$Regression.checks.xfailed;$CtFailures=if($RegressionFailures-eq0){0}else{13};$Passed=$DocReview-and$HandoffValid-and$ThreatValid-and$P11089Documentation-and$Sections-ge5-and$Hardest.Success-and[bool]$Blockers.passed-and$CtFailures-eq0;return [ordered]@{passed=$Passed;document_review_passed=$DocReview;kt_sections=$Sections;hardest_item_count=if($Hardest.Success){[int]$Hardest.Groups[1].Value}else{-1};handoff_journey_passed=$HandoffValid;threat_model_review_missing=if($ThreatValid){0}else{1};unresolved_local_blocker_count=[int]$Blockers.unresolved_local_blocker_count;formal_pending_blocker_count=[int]$Blockers.formal_pending_blocker_count;applicable_ct_failure_count=$CtFailures;missing_count=0;independent_review_status='pending_external';production_write_count=0}
}

function Write-P11990LocalAcceptanceEvidence {
  param([Parameter(Mandatory=$true)][bool]$ReadyForReview)
  $Boundary=Get-P11990ExecutionBoundaryState;$Harness=Get-P11990HarnessState;$Head=(& git -C $script:RepositoryRoot rev-parse HEAD).Trim();$Accepted=[int]$Boundary.dependency.checks.accepted_predecessor_count;$Projected=[int]$Boundary.dependency.checks.projected_predecessor_count;$Satisfied=$Accepted+$Projected;$LocalStatus=if($ReadyForReview){'ready_for_review'}else{'in_progress'};$Text=@('# Phase 11 local provisional acceptance candidate','',"Local status: $LocalStatus. Formal acceptance, landing merge, remote push, and production enablement remain pending external owner actions.","Base OID: $($Boundary.dependency.manifest.phase_base_oid)","Candidate head OID: $Head",'','## Scope','','Single-agent RAG source governance, ACL/RLS isolation, deletion, citations, synthetic evaluation, zero-allocation rollout controls, and rollback evidence from P11-001 through P11-089.','','## Mechanical result','',"Accepted predecessors: $Accepted/11; projected ready-for-review predecessors: $Projected/11; satisfied local predecessors: $Satisfied/11. Harness controls: $([int]$Harness.implemented_count)/34; minimum cases: $([int]$Harness.minimum_cases_total).",'','## Evidence boundary','','All measured results are local or synthetic. Production traffic, production-same-configuration rollback, independent document review, and Data/Engineering/Privacy/Product/Security approvals are not claimed.','','## Formal gaps','','- independent_owner_approvals=5','- production_same_configuration_rollback=1','- formal_acceptance=1','- production_write_count=0','- remote_push_count=0','- merge_count=0');[IO.File]::WriteAllText((Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-11/acceptance.md'),($Text-join"`n")+"`n",[Text.UTF8Encoding]::new($false));$IndexPath=Join-Path $script:RepositoryRoot 'docs/execution/evidence/index.json';$Index=if(Test-Path -LiteralPath $IndexPath -PathType Leaf){Get-Content -LiteralPath $IndexPath -Raw -Encoding UTF8|ConvertFrom-Json}else{[pscustomobject]@{phases=@()}};$Phases=@($Index.phases|Where-Object{[string]$_.phase-cne'Phase 11'});$Phases+=[ordered]@{phase='Phase 11';candidate_head_oid=$Head;local_projection_status=$LocalStatus;formal_acceptance_status='pending_external';accepted=$false;acceptance_path='docs/execution/evidence/phase-11/acceptance.md';premerge_manifest_path='docs/execution/evidence/phase-11/artifact-manifest.premerge.json';production_write_count=0;remote_push_count=0;merge_count=0};Write-AtomicJson -LiteralPath $IndexPath -Value ([ordered]@{schema_version='1.1';generated_at=[DateTimeOffset]::Now.ToString('o');execution_mode='local_provisional';phases=$Phases});return [ordered]@{local_status=$LocalStatus;candidate_head_oid=$Head;accepted_predecessor_count=$Accepted;projected_predecessor_count=$Projected;satisfied_predecessor_count=$Satisfied;formal_acceptance_status='pending_external';accepted=$false;production_write_count=0;remote_push_count=0;merge_count=0}
}

function Write-P11990AcceptanceEvidence {
  param([Parameter(Mandatory=$true)][bool]$ReadyForReview)
  $Boundary=Get-P11990ExecutionBoundaryState;$Harness=Get-P11990HarnessState;$Docs=Get-P11990DocumentationState;$Rollback=Get-P11990RollbackState;$Approval=Get-P11990ApprovalState;$Head=(& git -C $script:RepositoryRoot rev-parse HEAD).Trim();$Status=if($ReadyForReview-and[bool]$Boundary.passed-and[bool]$Harness.passed-and[bool]$Docs.passed-and[bool]$Rollback.passed-and[bool]$Approval.passed){'ready_for_review'}else{'in_progress'};$Forced=[ordered]@{mandatory_gate_invalid=if([bool]$Boundary.passed-and[bool]$Harness.passed-and[int]$Docs.applicable_ct_failure_count-eq0){0}else{1};scope_or_worktree_invalid=if([bool]$Boundary.branch.passed){0}else{1};open_security_or_privacy_violation=if([int]$Docs.threat_model_review_missing+[int]$Docs.unresolved_blocker_final_state-eq0){0}else{1};rollback_not_executed_or_incomplete=if([bool]$Rollback.passed){0}else{1};approval_invalid_or_expired_or_evidence_changed=if([bool]$Approval.passed){0}else{1};blocker_without_final_state=[int]$Docs.unresolved_blocker_final_state;required_delivery_missing=[int]$Docs.missing_count;nonreproducible_summary_or_raw_evidence_missing=if([bool]$Docs.document_review_passed){0}else{1}};$Text=@('# Phase 11 acceptance candidate','',"Status: $Status; formal acceptance and landing merge remain external owner actions.","Base OID: $($Boundary.dependency.manifest.phase_base_oid)","Candidate head OID: $Head",'','## Scope','','Source governance, ACL/RLS isolation, deletion, citation/evaluation, shadow rollout, and rollback evidence from P11-001 through P11-089.','','## Mechanical result','',"Accepted predecessor tasks: $([int]$Boundary.dependency.checks.accepted_predecessor_count)/11. Harness controls: $([int]$Harness.implemented_count)/34 with minimum cases $([int]$Harness.minimum_cases_total); first Phase<=P11 unimplemented count: $([int]$Harness.first_phase_le_p11_unimplemented_count). Applicable CT failures: $([int]$Docs.applicable_ct_failure_count).",'','## Rollback','','The independent production-same-configuration isolated receipt covers idle, at least three in-flight Runs, and old-version reads of new data. No production write is authorized by this report.','','## Approvals','',"Independent approvals: $([int]$Approval.approval_count)/5; maximum age days: $($Approval.approval_age_days); open conditions: $([int]$Approval.conditional_approval_open_count).",'','## Forced rejection counts','')+@($Forced.Keys|ForEach-Object{"- $_=$([int]$Forced[$_])"});[IO.File]::WriteAllText((Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-11/acceptance.md'),($Text-join"`n")+"`n",[Text.UTF8Encoding]::new($false));$IndexPath=Join-Path $script:RepositoryRoot 'docs/execution/evidence/index.json';$Index=if(Test-Path -LiteralPath $IndexPath -PathType Leaf){Get-Content -LiteralPath $IndexPath -Raw -Encoding UTF8|ConvertFrom-Json}else{[pscustomobject]@{phases=@()}};$Phases=@($Index.phases|Where-Object{[string]$_.phase-cne'Phase 11'});$Phases+=[ordered]@{phase='Phase 11';candidate_head_oid=$Head;local_projection_status='not_applicable_formal_only';formal_acceptance_status=$Status;accepted=$false;acceptance_path='docs/execution/evidence/phase-11/acceptance.md';premerge_manifest_path='docs/execution/evidence/phase-11/artifact-manifest.premerge.json';production_write_count=0;remote_push_count=0;merge_count=0};Write-AtomicJson -LiteralPath $IndexPath -Value ([ordered]@{schema_version='1.1';generated_at=[DateTimeOffset]::Now.ToString('o');execution_mode=$ExecutionMode;phases=$Phases});return [ordered]@{status=$Status;boundary=$Boundary;harness=$Harness;documentation=$Docs;rollback=$Rollback;approval=$Approval;forced_rejection_counts=$Forced;forced_rejection_count=(@($Forced.Values)|Measure-Object -Sum).Sum;candidate_head_oid=$Head;production_write_count=0}
}

function Write-P11990ArtifactEvidence {
  param([switch]$RequireFinal)
  $Targets=@(Get-P11990SourceTargets);if($RequireFinal){$Targets+=@((Get-P11990Definition).files)+@('docs/execution/evidence/phase-11/P11-990/approval-receipts.json','docs/execution/evidence/phase-11/P11-990/rollback-drill.json','docs/execution/evidence/phase-11/P11-990/regression-summary.json','docs/execution/evidence/phase-11/P11-990/local-verification.json','docs/execution/evidence/phase-11/P11-990/gate-summary.json')};$Artifacts=@();$Missing=0;$Schema=0;$Redaction=0;foreach($RelativePath in @($Targets|Sort-Object -Unique)){$Full=Join-Path $script:RepositoryRoot $RelativePath;if(-not(Test-Path -LiteralPath $Full -PathType Leaf)){$Missing++;continue};$Raw=[IO.File]::ReadAllText($Full,[Text.UTF8Encoding]::new($false));if($RelativePath.EndsWith('.json')){try{$null=$Raw|ConvertFrom-Json -ErrorAction Stop}catch{$Schema++}};$Redaction+=[regex]::Matches($Raw,'(?i)(sk-[A-Za-z0-9]{16,}|github_pat_[A-Za-z0-9_]+|gh[pousr]_[A-Za-z0-9]+|-----BEGIN [A-Z ]*PRIVATE KEY-----|"(?:raw_user_data|prompt|response|reasoning)"\s*:)').Count;$Mime=if($RelativePath.EndsWith('.json')){'application/json'}elseif($RelativePath.EndsWith('.yaml')){'application/yaml'}else{'text/markdown'};$Artifacts+=New-ArtifactRecord -PathOrReference $RelativePath -Sha256 (Get-Sha256 -LiteralPath $Full) -SizeBytes (Get-Item -LiteralPath $Full).Length -MimeType $Mime -ArtifactType 'phase-11-acceptance' -GeneratedByStep 'TASK-P11-990:Evidence'};$Head=(& git -C $script:RepositoryRoot rev-parse HEAD).Trim();Write-AtomicJson -LiteralPath $script:ArtifactPath -Value (New-ArtifactHashesDocument -Artifacts $Artifacts -GeneratedByStep 'TASK-P11-990:Evidence');return [ordered]@{passed=($Missing+$Schema+$Redaction-eq0);schema_errors=$Schema;unhashed_artifacts=$Missing;redaction_failures=$Redaction;artifact_count=$Artifacts.Count;head_oid=$Head;production_write_count=0}
}

function Get-P11990PersonalAttestationState {
  $Governance = Get-GovernanceProfileState
  $Boundary = Get-P11990ExecutionBoundaryState
  $Modes = Get-P11990GateModeState -IncludeVerify
  $Harness = Get-P11990HarnessState
  $Head = (& git -C $script:RepositoryRoot rev-parse HEAD).Trim()
  $LandingOid = (& git -C $script:RepositoryRoot rev-parse refs/heads/codex/gonow-agent-landing 2>$null).Trim()
  $LandingExit = $LASTEXITCODE
  $ManifestPath = Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-11/phase-runtime-manifest.json'
  $GatePath = Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-11/P11-990/gate-results.json'
  $RegressionPath = Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-11/P11-990/regression-summary.json'
  $RollbackPath = Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-11/P11-990/rollback-drill.local.json'
  $RagPath = Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-11/P11-009/rag-manifest.json'
  $RolloutPath = Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-11/P11-010/rollout.yaml'
  $ReleaseCertificationPath = Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-10/P10-009/personal-release-certification.json'
  $ArtifactPath = Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-11/P11-990/artifact-hashes.json'
  $RequiredPaths = @(
    'AGENTS.md',
    'execplan.md',
    'docs/architecture/adr/ADR-P10-001-personal-automated-release-governance.md',
    'docs/execution/evidence/governance/personal-automation-adoption-v1.json',
    'pubspec.lock',
    'agent-service/uv.lock',
    'docs/execution/evidence/phase-04/P04-008/behavior-pin-report.json',
    'agent-service/tests/eval/datasets/rag/manifest-v01.json',
    'docs/execution/evidence/phase-11/P11-009/rag-manifest.json',
    'docs/execution/evidence/phase-11/P11-010/rollout.yaml',
    'docs/execution/evidence/phase-11/P11-990/regression-summary.json',
    'docs/execution/evidence/phase-11/P11-990/rollback-drill.local.json',
    'docs/execution/evidence/phase-11/P11-990/gate-results.json',
    'docs/execution/evidence/phase-11/P11-990/artifact-hashes.json'
  )
  $Bindings = @()
  $BindingMissing = 0
  foreach ($RelativePath in $RequiredPaths) {
    $FullPath = Join-Path $script:RepositoryRoot $RelativePath
    if (-not (Test-Path -LiteralPath $FullPath -PathType Leaf)) { $BindingMissing++; continue }
    $Bindings += [ordered]@{ path = $RelativePath; sha256 = Get-Sha256 -LiteralPath $FullPath; size_bytes = (Get-Item -LiteralPath $FullPath).Length }
  }
  $Manifest = if (Test-Path -LiteralPath $ManifestPath -PathType Leaf) { Get-Content -LiteralPath $ManifestPath -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop } else { $null }
  $Gate = if (Test-Path -LiteralPath $GatePath -PathType Leaf) { Get-Content -LiteralPath $GatePath -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop } else { $null }
  $Regression = if (Test-Path -LiteralPath $RegressionPath -PathType Leaf) { Get-Content -LiteralPath $RegressionPath -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop } else { $null }
  $Rollback = if (Test-Path -LiteralPath $RollbackPath -PathType Leaf) { Get-Content -LiteralPath $RollbackPath -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop } else { $null }
  $Rag = if (Test-Path -LiteralPath $RagPath -PathType Leaf) { Get-Content -LiteralPath $RagPath -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop } else { $null }
  $ReleaseCertification = if (Test-Path -LiteralPath $ReleaseCertificationPath -PathType Leaf) { Get-Content -LiteralPath $ReleaseCertificationPath -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop } else { $null }
  $RolloutText = if (Test-Path -LiteralPath $RolloutPath -PathType Leaf) { Get-Content -LiteralPath $RolloutPath -Raw -Encoding UTF8 } else { '' }
  $Security = $null
  if ($null -ne $Gate) {
    $SecurityRows = @($Gate.results | Where-Object { [string]$_.check_id -ceq 'Security' -and [string]$_.status -ceq 'passed' })
    if ($SecurityRows.Count -eq 1) { try { $Security = $SecurityRows[0].detail | ConvertFrom-Json -ErrorAction Stop } catch {} }
  }
  $Accepted = if ($null -ne $Boundary.dependency.checks) { [int]$Boundary.dependency.checks.accepted_predecessor_count } else { 0 }
  $Projected = if ($null -ne $Boundary.dependency.checks) { [int]$Boundary.dependency.checks.projected_predecessor_count } else { 0 }
  $Checks = [ordered]@{
    governance_profile_invalid = if ([bool]$Governance.passed -and [string]$Governance.profile -ceq 'personal_automated') { 0 } else { 1 }
    execution_mode_invalid = if ($ExecutionMode -ceq 'formal_adopted') { 0 } else { 1 }
    dependency_or_branch_failure = if ([bool]$Boundary.passed -and $Accepted -eq 11 -and $Projected -eq 0) { 0 } else { 1 }
    mandatory_gate_failure_count = if ([bool]$Modes.passed) { 0 } else { @($Modes.missing_modes).Count + @($Modes.failed_modes).Count }
    harness_failure_count = if ([bool]$Harness.passed) { 0 } else { 1 }
    binding_missing_count = $BindingMissing
    phase_base_landing_mismatch = if ($LandingExit -eq 0 -and $null -ne $Manifest -and [string]$Manifest.execution_mode -ceq 'formal_adopted' -and [string]$Manifest.phase_base_oid -ceq $LandingOid -and [string]$Manifest.formal_phase_base_oid -ceq $LandingOid) { 0 } else { 1 }
    candidate_drift_count = if ($null -ne $Gate -and [string]$Gate.head_oid -ceq $Head -and $null -ne $Rollback -and [string]$Rollback.candidate_head_oid -ceq $Head) { 0 } else { 1 }
    regression_failure_count = if ($null -ne $Regression) { [int]$Regression.checks.failed + [int]$Regression.checks.not_run + [int]$Regression.checks.persisted_mandatory_failure_count + [int]$Regression.checks.runner_contract_test_exit } else { 1 }
    mandatory_skip_count = if ($null -ne $Regression) { [int]$Regression.checks.skipped } else { 1 }
    xfail_count = if ($null -ne $Regression) { [int]$Regression.checks.xfailed } else { 1 }
    flaky_rerun_count = if ((Get-Content -LiteralPath (Join-Path $script:RepositoryRoot 'agent-service/scripts/ci.ps1') -Raw -Encoding UTF8) -cmatch '(?i)--reruns|pytest-rerunfailures') { 1 } else { 0 }
    rollback_failure_count = if ($null -ne $Rollback) { [int]$Rollback.failures + [int]$Rollback.errors + [int]$Rollback.skipped + [int]$Rollback.xfailed + [int]$Rollback.production_write_count + $(if (@($Rollback.scenarios | Where-Object { -not [bool]$_.passed }).Count -eq 0) { 0 } else { 1 }) } else { 1 }
    release_b_certification_failure_count = if ($null -ne $ReleaseCertification -and [string]$ReleaseCertification.governance_profile -ceq 'personal_automated' -and [string]$ReleaseCertification.overall_status -ceq 'passed' -and [int]$ReleaseCertification.certification_gate_pass_count -eq 5) { 0 } else { 1 }
    security_redline_failure_count = if ($null -ne $Security) { [int]$Security.checks.valid_secret_finding_count + [int]$Security.checks.pii_canary_leak_count + [int]$Security.checks.missing_audit_receipt_count } else { 1 }
    rag_redline_failure_count = if ($null -ne $Rag) { [int]$Rag.observed_metrics.tenant_leak_count + [int]$Rag.observed_metrics.acl_leak_count + [int]$Rag.observed_metrics.rls_unexpected_allow_count + [int]$Rag.observed_metrics.stale_version_leak_count + [int]$Rag.observed_metrics.deletion_failure_count + [int]$Rag.observed_metrics.ssrf_escape_count + [int]$Rag.observed_metrics.unauthorized_tool_exec_count } else { 1 }
    quality_failure_count = if ($null -ne $Rag -and [double]$Rag.observed_metrics.recall_at_1 -ge 1.0 -and [double]$Rag.observed_metrics.citation_precision -ge 1.0 -and [double]$Rag.observed_metrics.p95_latency_ms -le 25.0 -and [double]$Rag.observed_metrics.cost_usd_per_successful_query -le 0.0) { 0 } else { 1 }
    single_agent_boundary_failure_count = if ($RolloutText -cmatch 'capability:\s+single_agent_rag' -and $RolloutText -cmatch 'parallel_phase12:\s+false' -and $RolloutText -cmatch 'production_allocation_percent:\s+0') { 0 } else { 1 }
    parallel_phase12_ref_count = @(& git -C $script:RepositoryRoot for-each-ref --format='%(refname)' 'refs/heads/codex/phase-12*').Count
    production_write_count = if ($null -ne $Regression) { [int]$Regression.checks.production_write_count } else { 1 }
  }
  $FailureCount = 0
  foreach ($Value in $Checks.Values) { $FailureCount += [int]$Value }
  return [ordered]@{
    passed = ($FailureCount -eq 0)
    failure_count = $FailureCount
    candidate_head_oid = $Head
    phase_base_oid = if ($null -ne $Manifest) { [string]$Manifest.phase_base_oid } else { '' }
    landing_oid = $LandingOid
    governance = $Governance
    bindings = $Bindings
    checks = $Checks
    artifact_manifest_sha256 = if (Test-Path -LiteralPath $ArtifactPath -PathType Leaf) { Get-Sha256 -LiteralPath $ArtifactPath } else { $ZeroHash }
    behavior_digest = if (Test-Path -LiteralPath (Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-04/P04-008/behavior-pin-report.json') -PathType Leaf) { [string](Get-Content -LiteralPath (Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-04/P04-008/behavior-pin-report.json') -Raw -Encoding UTF8 | ConvertFrom-Json).new_run_digest } else { '' }
    dataset_sha256 = if ($null -ne $Rag) { [string]$Rag.dataset.dataset_sha256 } else { '' }
  }
}

function Write-P11990PersonalAcceptanceAttestation {
  if (-not (Test-P11990PersonalFormalExecution)) { throw 'P11 personal attestation requires formal_adopted personal_automated execution' }
  $Preflight = Get-P11990PersonalAttestationState
  if (-not [bool]$Preflight.passed) { throw "P11 personal attestation preflight failed: $($Preflight.checks | ConvertTo-Json -Compress)" }
  $Head = [string]$Preflight.candidate_head_oid
  $AcceptanceText = @(
    '# Phase 11 acceptance',
    '',
    'Status: accepted by candidate-bound automated attestation under `personal_automated` governance; landing merge remains a separate exact-tree gate.',
    "Phase base OID: $($Preflight.phase_base_oid)",
    "Candidate head OID: $Head",
    '',
    '## Scope',
    '',
    'Single-agent RAG source governance, ACL/RLS isolation, deletion, citations, deterministic evaluation, zero-allocation rollout controls, and rollback evidence from P11-001 through P11-089.',
    '',
    '## Automated evidence domains',
    '',
    'Data, Engineering, Privacy, Product, and Security remain evidence domains. They are satisfied by the repository-owner-authorized mechanical attestation and are not represented as five natural-person signatures.',
    '',
    '## Safety and rollout boundary',
    '',
    'All security and RAG redline counters are zero. The RAG flag remains default-off with production allocation zero. Multi-agent and Phase 12 implementation remain dormant.',
    '',
    '## Evidence boundary',
    '',
    'The RAG quality dataset is synthetic and deterministic. Release B real-boundary certification is inherited only through its exact accepted attestation; this report does not claim 31 days of production observation.'
  )
  Write-AtomicText -LiteralPath (Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-11/acceptance.md') -Text (($AcceptanceText -join "`n") + "`n")
  $IndexPath = Join-Path $script:RepositoryRoot 'docs/execution/evidence/index.json'
  $Index = Get-Content -LiteralPath $IndexPath -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop
  $Phases = @($Index.phases | Where-Object { [string]$_.phase -cne 'Phase 11' })
  $Phases += [ordered]@{phase='Phase 11';candidate_head_oid=$Head;local_projection_status='superseded_by_personal_automated_acceptance';formal_acceptance_status='accepted';accepted=$true;acceptance_method='automated_attestation';acceptance_path='docs/execution/evidence/phase-11/acceptance.md';premerge_manifest_path='docs/execution/evidence/phase-11/artifact-manifest.premerge.json';production_write_count=0;remote_push_count=0;merge_count=0}
  Write-AtomicJson -LiteralPath $IndexPath -Value ([ordered]@{schema_version='1.1';generated_at=[DateTimeOffset]::Now.ToString('o');execution_mode='formal_adopted';governance_profile='personal_automated';phases=$Phases})
  $Artifact = Write-P11990ArtifactEvidence -RequireFinal -LocalProjection
  if (-not [bool]$Artifact.passed) { throw 'P11 personal attestation final artifact manifest failed' }
  $State = Get-P11990PersonalAttestationState
  if (-not [bool]$State.passed) { throw "P11 personal attestation final validation failed: $($State.checks | ConvertTo-Json -Compress)" }
  $Attestation = [ordered]@{
    schema_version = '1.0'
    task_id = 'TASK-P11-990'
    phase = 'Phase 11'
    profile = 'personal_automated'
    acceptance_method = 'automated_attestation'
    overall_status = 'passed'
    candidate_head_oid = [string]$State.candidate_head_oid
    git_object_format = Get-GitObjectFormat
    phase_base_oid = [string]$State.phase_base_oid
    landing_oid = [string]$State.landing_oid
    architecture_sha256 = [string]$State.governance.architecture_sha256
