  $StatusValid=$null-ne$Status-and[string]$Status.task_id-ceq'TASK-P12-001'-and[string]$Status.status-ceq'accepted'-and[bool]$Status.reviewer_independent-and[string]$Status.head_oid-ceq$SourceOid-and[string]$Status.evidence_sha256-ceq[string]$Records.gate.sha256;$ApprovalValid=$null-ne$Approval-and[string]$Approval.task_id-ceq'TASK-P12-001'-and[string]$Approval.selected-in@('12A','12B','12C','12D','none')-and-not[bool]$Approval.raw_user_data_included;$VerificationValid=$null-ne$Verification-and[string]$Verification.task_id-ceq'TASK-P12-001'-and[bool]$Verification.checks.primary_assertion_passed-and[double]$Verification.checks.approval_age_days-le14-and[string]$Verification.source_references.p12_000_artifact_sha256-ceq[string]$Approval.p12_000_artifact_sha256;$ManifestValid=$null-ne$Manifest-and[string]$Manifest.phase-ceq'Phase 12'-and[string]$Manifest.execution_mode-ceq'formal_adopted'-and[int]$Manifest.prior_phase_regression_failures+[int]$Manifest.not_run+[int]$Manifest.future_oid_literal_count+[int]$Manifest.base_drift+[int]$Manifest.source_hash_drift-eq0;$PriorPath='docs/execution/evidence/phase-12/P12-002/selection.json';& git -C $script:RepositoryRoot cat-file -e "${SourceRef}:$PriorPath" 2>$null;$PriorAccepted=if($LASTEXITCODE-eq0){1}else{0};$ChoiceMap=@{'12A'='memory';'12B'='cost_router';'12C'='multi_agent';'12D'='domain_command';'none'='none'};$ApprovedChoice=if($null-ne$Approval-and$ChoiceMap.ContainsKey([string]$Approval.selected)){$ChoiceMap[[string]$Approval.selected]}else{''}
