  $Base=Get-RelC000BranchState;$Head=(@(& git -C $script:RepositoryRoot rev-parse HEAD 2>$null)-join'').Trim();$HeadExit=$LASTEXITCODE;$Top=(@(& git -C $script:RepositoryRoot rev-parse --show-toplevel 2>$null)-join'').Trim();$TopExit=$LASTEXITCODE;$TopNormalized=if($TopExit-eq0){[IO.Path]::GetFullPath($Top).TrimEnd('\')}else{''};$ReceiptPath=Join-Path $script:RepositoryRoot 'docs\execution\evidence\phase-12\P12-002.json';$Receipt=$null;if(Test-Path -LiteralPath $ReceiptPath -PathType Leaf){try{$Receipt=Get-Content -LiteralPath $ReceiptPath -Raw -Encoding UTF8|ConvertFrom-Json -ErrorAction Stop}catch{}};$ExpectedHead=if($null-ne$Receipt-and[string]$Receipt.new_sha-cmatch'^[0-9a-f]{40}$'){[string]$Receipt.new_sha}else{[string]$Dependency.p12_001_head_sha};$Paths=@(Get-P12002ChangedPaths);$Unexpected=@($Paths|Where-Object{-not(Test-P12002PathAllowed -RelativePath $_)});$Worktrees=@(& git -C $script:RepositoryRoot worktree list --porcelain 2>$null);$WorktreeExit=$LASTEXITCODE;$SpecialistWorktrees=@($Worktrees|Where-Object{$_-match'(?i)(phase-12a|phase-12b|phase-12c|phase-12d|phase-11)'}).Count;$Gitlinks=@(& git -C $script:RepositoryRoot ls-files --stage 2>$null|Where-Object{$_-cmatch'^160000\s'});$GitlinkExit=$LASTEXITCODE;$Credentials=@(& git -C $script:RepositoryRoot ls-files --others --exclude-standard 2>$null|Where-Object{$_-cmatch'(^|/)(\.env($|\.)|id_rsa|id_ed25519|.*\.(pem|key|p12|pfx))$'});$CredentialExit=$LASTEXITCODE;$Nested=@(Get-ChildItem -LiteralPath $script:RepositoryRoot -Recurse -Force -Filter .git -ErrorAction SilentlyContinue|Where-Object{$_.FullName-cne(Join-Path $script:RepositoryRoot '.git')});$QueryFailures=[int]$Base.query_failure_count+$HeadExit+$TopExit+$WorktreeExit+$GitlinkExit+$CredentialExit;$Passed=[bool]$Dependency.passed-and$QueryFailures-eq0-and[int]$Base.specialist_branch_count+$SpecialistWorktrees+$Unexpected.Count+$Gitlinks.Count+$Credentials.Count+$Nested.Count-eq0-and[string]$Base.current_branch-ceq'codex/release-c-governance'-and$Head-ceq$ExpectedHead-and[string]$Base.governance_ref_oid-ceq$ExpectedHead-and$TopNormalized-ceq'D:\GO_NOW-release-c-governance';return [ordered]@{passed=$Passed;current_branch=[string]$Base.current_branch;current_head_oid=$Head;governance_ref_oid=[string]$Base.governance_ref_oid;worktree_path=$TopNormalized;specialist_branch_count=[int]$Base.specialist_branch_count;specialist_worktree_count=$SpecialistWorktrees;unexpected_path_count=$Unexpected.Count;gitlink_count=$Gitlinks.Count;nested_git_count=$Nested.Count;credential_like_untracked_count=$Credentials.Count;query_failure_count=$QueryFailures;production_write_count=0}
