function Test-P12WorkPackageTask {
  param([Parameter(Mandatory=$true)][string]$TaskIdValue)
  return $TaskIdValue-in@('TASK-P12A-000','TASK-P12B-000','TASK-P12C-000','TASK-P12D-000')
}

