function Get-P12WorkPackageGateModeState {
  $RequiredModes=@('Preflight','WorkPreflight','WorksetVerify','Verify','Security','RollbackVerify','Evidence');if(-not(Test-Path -LiteralPath $script:GatePath -PathType Leaf)){return [ordered]@{passed=$false;missing_modes=$RequiredModes;failed_modes=@()}};$Results=@((Get-Content -LiteralPath $script:GatePath -Raw -Encoding UTF8|ConvertFrom-Json).results);$MissingModes=@($RequiredModes|Where-Object{$ModeName=$_;@($Results|Where-Object{[string]$_.check_id-ceq$ModeName}).Count-ne1});$FailedModes=@($RequiredModes|Where-Object{$ModeName=$_;$Rows=@($Results|Where-Object{[string]$_.check_id-ceq$ModeName});$Rows.Count-eq1-and[string]$Rows[0].status-cne'passed'});return [ordered]@{passed=($MissingModes.Count-eq0-and$FailedModes.Count-eq0);missing_modes=$MissingModes;failed_modes=$FailedModes}
}

function Get-P12WorkPackageChangedPaths {
  $Paths=@(& git -C $script:RepositoryRoot diff --name-only HEAD --);$Paths+=@(& git -C $script:RepositoryRoot ls-files --others --exclude-standard);return @($Paths|Where-Object{$_}|ForEach-Object{$_.Replace('\','/')}|Sort-Object -Unique)
}

function Test-P12WorkPackagePathAllowed {
  param([Parameter(Mandatory=$true)][object]$Definition,[Parameter(Mandatory=$true)][string]$RelativePath)
  if($RelativePath-in@([string]$Definition.adr_path,[string]$Definition.plan_path,"docs/execution/status/$($Definition.task_id).json")){return $true};return $RelativePath.StartsWith([string]$Definition.evidence_directory,[StringComparison]::Ordinal)
}

