function Get-P12089GateModeState {
  $RequiredModes=@('Preflight','WorkPreflight','HarnessCatalogAggregate','StatusBoardAggregate','Documentation','HandoffVerification','Security','Evidence','RollbackVerify','WorksetVerify')
  if(-not(Test-Path -LiteralPath $script:GatePath -PathType Leaf)){return [ordered]@{passed=$false;missing_modes=$RequiredModes;failed_modes=@()}}
  $Results=@((Get-Content -LiteralPath $script:GatePath -Raw -Encoding UTF8|ConvertFrom-Json).results)
  $MissingModes=@($RequiredModes|Where-Object{$ModeName=$_;@($Results|Where-Object{[string]$_.check_id-ceq$ModeName}).Count-ne1})
  $FailedModes=@($RequiredModes|Where-Object{$ModeName=$_;$Rows=@($Results|Where-Object{[string]$_.check_id-ceq$ModeName});$Rows.Count-eq1-and[string]$Rows[0].status-cne'passed'})
  return [ordered]@{passed=($MissingModes.Count-eq0-and$FailedModes.Count-eq0);missing_modes=$MissingModes;failed_modes=$FailedModes}
}

function Get-P12089ChangedPaths {
  $Paths=@(& git -C $script:RepositoryRoot diff --name-only HEAD --)
  $Paths+=@(& git -C $script:RepositoryRoot ls-files --others --exclude-standard)
  $PhaseBase=Get-PhaseBaseOid
  foreach($Commit in @(& git -C $script:RepositoryRoot log --format=%H --grep='TASK-P12-089' "$PhaseBase..HEAD")){
    if($Commit-cmatch'^[0-9a-f]{40,64}$'){$Paths+=@(& git -C $script:RepositoryRoot diff-tree --no-commit-id --name-only -r $Commit)}
  }
  return @($Paths|Where-Object{$_}|ForEach-Object{$_.Replace('\','/')}|Sort-Object -Unique)
}

function Test-P12089PathAllowed {
  param([Parameter(Mandatory=$true)][string]$RelativePath)
  $AllowedExact=@(
    'README.md','docs/architecture/release-c-selection.md','docs/runbooks/release-c-governance.md','docs/api/release-c-selection.md',
    'docs/architecture/threat-model/phase-12-review.json','docs/execution/evidence/phase-12/change-summary.md',
    'docs/execution/evidence/phase-12/knowledge-transfer.md','docs/execution/evidence/phase-12/star-records.md',
    'docs/execution/evidence/phase-12/artifact-manifest.premerge.json','docs/execution/schemas/harness-test-catalog.yaml',
    'docs/execution/status/task-board.json','docs/execution/status/task-board.md','docs/execution/status/TASK-P12-089.json'
  )
  if($RelativePath-in$AllowedExact){return $true}
  return $RelativePath.StartsWith('docs/execution/evidence/phase-12/P12-089/',[StringComparison]::Ordinal)-or
    $RelativePath.StartsWith('docs/execution/evidence/phase-12/improvements/',[StringComparison]::Ordinal)
}

