function Invoke-ConditionalReleaseCEntryRegression {
  param([Parameter(Mandatory=$true)][string]$EntryTaskId,[Parameter(Mandatory=$true)][object]$Dependency,[Parameter(Mandatory=$true)][string]$ReportPath)
  $Existing=if(Test-Path -LiteralPath $ReportPath -PathType Leaf){try{Get-Content -LiteralPath $ReportPath -Raw -Encoding UTF8|ConvertFrom-Json -ErrorAction Stop}catch{$null}}else{$null}
  if($null-ne$Existing-and[string]$Existing.task_id-ceq$EntryTaskId-and[string]$Existing.phase_base_oid-ceq[string]$Dependency.accepted_landing_sha-and[string]$Existing.governance_head_oid-ceq[string]$Dependency.governance_head_oid-and[string]$Existing.path_selection_sha256-ceq[string]$Dependency.path_selection_sha256-and[int]$Existing.failure_count-eq0){return $Existing}
  $AgentRoot=Join-Path $script:TaskEvidenceDirectory 'phase-entry-ci';$ProvisionRoot=Join-Path $script:TaskEvidenceDirectory 'phase-entry-provision'
  foreach($Directory in @($AgentRoot,$ProvisionRoot)){if(-not(Test-Path -LiteralPath $Directory -PathType Container)){New-Item -ItemType Directory -Path $Directory -Force|Out-Null}}
  $TrackedBefore=@(& git -C $script:RepositoryRoot diff --name-only)
  $Provision=Invoke-RedactedExternal -Executable 'powershell.exe' -Arguments @('-NoProfile','-ExecutionPolicy','Bypass','-File',(Join-Path $script:RepositoryRoot 'agent-service\scripts\ci.ps1'),'-Stage','Format','-ReportRoot',$ProvisionRoot)
  $Python=Join-Path $script:RepositoryRoot 'agent-service\.venv\Scripts\python.exe'
  $Warmup=if(Test-Path -LiteralPath $Python -PathType Leaf){Invoke-RedactedExternal -Executable $Python -Arguments @('-c','from ortools.sat.python import cp_model; assert cp_model.CpModel is not None')}else{[ordered]@{exit_code=1;duration_seconds=0;output_line_count=0}}
  $Agent=if([int]$Provision.exit_code-eq0-and[int]$Warmup.exit_code-eq0){Invoke-RedactedExternal -Executable 'powershell.exe' -Arguments @('-NoProfile','-ExecutionPolicy','Bypass','-File',(Join-Path $script:RepositoryRoot 'agent-service\scripts\ci.ps1'),'-Stage','All','-ReportRoot',$AgentRoot)}else{[ordered]@{exit_code=1;duration_seconds=0;output_line_count=0}}
  $SummaryPath=Join-Path $AgentRoot 'ci-summary.json';$Summary=if(Test-Path -LiteralPath $SummaryPath -PathType Leaf){Get-Content -LiteralPath $SummaryPath -Raw -Encoding UTF8|ConvertFrom-Json}else{$null}
  $UnitTests=0;$ContractTests=0;$AgentFailures=0;$AgentSkipped=0
  foreach($Entry in @(@{path=(Join-Path $AgentRoot 'unit.xml');kind='unit'},@{path=(Join-Path $AgentRoot 'contract.xml');kind='contract'})){
    if(-not(Test-Path -LiteralPath $Entry.path -PathType Leaf)){$AgentFailures++;continue}
    [xml]$Xml=Get-Content -LiteralPath $Entry.path -Raw -Encoding UTF8;$Suites=if($null-ne$Xml.testsuites.testsuite){@($Xml.testsuites.testsuite)}else{@($Xml.testsuite)};$Count=0
    foreach($Suite in $Suites){$Count+=[int]$Suite.tests;$AgentFailures+=[int]$Suite.failures+[int]$Suite.errors;$AgentSkipped+=[int]$Suite.skipped}
    if($Entry.kind-ceq'unit'){$UnitTests=$Count}else{$ContractTests=$Count}
  }
  $AgentGateFailures=if($null-eq$Summary){1}else{@($Summary.results|Where-Object{[int]$_.exit_code-ne0}).Count};$AgentXfailed=if($null-eq$Summary){0}else{[int]$Summary.xfail_count};$AgentCountFailure=if($UnitTests-lt542-or$ContractTests-lt144){1}else{0}
  $ToolchainPath=Join-Path $script:RepositoryRoot 'docs\execution\supply-chain\phase-boot\BOOT-005\toolchain-lock.json';$Toolchain=if(Test-Path -LiteralPath $ToolchainPath -PathType Leaf){Get-Content -LiteralPath $ToolchainPath -Raw -Encoding UTF8|ConvertFrom-Json}else{$null};$Flutter=if($null-ne$Toolchain){[string]$Toolchain.flutter.executable}else{''}
  $PackageConfig=Join-Path $script:RepositoryRoot '.dart_tool\package_config.json';$LockPath=Join-Path $script:RepositoryRoot 'pubspec.lock';$LockBefore=if(Test-Path -LiteralPath $LockPath){Get-Sha256 -LiteralPath $LockPath}else{''};$FlutterProvision=[ordered]@{exit_code=0;duration_seconds=0;output_line_count=0};$FlutterProvisionState='existing'
  if(-not(Test-Path -LiteralPath $PackageConfig -PathType Leaf)-and-not[string]::IsNullOrWhiteSpace($Flutter)){$FlutterProvision=Invoke-RedactedExternal -Executable $Flutter -Arguments @('pub','get');$FlutterProvisionState='created'}
  $LockAfter=if(Test-Path -LiteralPath $LockPath){Get-Sha256 -LiteralPath $LockPath}else{''};$TrackedAfter=@(& git -C $script:RepositoryRoot diff --name-only);$UnexpectedProvision=@($TrackedAfter|Where-Object{$_-notin$TrackedBefore});$FlutterProvisionFailure=if([int]$FlutterProvision.exit_code-ne0-or-not(Test-Path -LiteralPath $PackageConfig -PathType Leaf)-or$LockBefore-cne$LockAfter-or$UnexpectedProvision.Count-ne0-or[string]::IsNullOrWhiteSpace($Flutter)){1}else{0}
  $Probe=Join-Path $script:RepositoryRoot '.dart_tool\gonow-p11-entry';if(-not(Test-Path -LiteralPath $Probe -PathType Container)){New-Item -ItemType Directory -Path $Probe -Force|Out-Null}
  $Targets=@('test/api/generated_client_contract_test.dart');$ItineraryTests=Join-Path $script:RepositoryRoot 'test\itinerary_agent';if(Test-Path -LiteralPath $ItineraryTests -PathType Container){$Targets+=@(Get-ChildItem -LiteralPath $ItineraryTests -File -Filter '*.dart'|ForEach-Object{$_.FullName.Substring($script:RepositoryRoot.Length+1).Replace('\','/')})}
  $CopyMismatch=0;foreach($SourceRelative in @('integration_test/itinerary_agent_journey_test.dart','integration_test/itinerary_agent_weak_network_test.dart','integration_test/itinerary_agent_accessibility_test.dart')){$Source=Join-Path $script:RepositoryRoot $SourceRelative;$Destination=Join-Path $Probe ([IO.Path]::GetFileName($SourceRelative));if(-not(Test-Path -LiteralPath $Source -PathType Leaf)){$CopyMismatch++;continue};Copy-Item -LiteralPath $Source -Destination $Destination -Force;if((Get-Sha256 -LiteralPath $Source)-cne(Get-Sha256 -LiteralPath $Destination)){$CopyMismatch++};$Targets+='.dart_tool/gonow-p11-entry/'+[IO.Path]::GetFileName($SourceRelative)}
  $FlutterExit=1;$FlutterStdout='';if($FlutterProvisionFailure-eq0){Push-Location $script:RepositoryRoot;try{$Start=[Diagnostics.ProcessStartInfo]::new();$Start.FileName=$Flutter;$Start.Arguments='test --no-pub '+($Targets-join' ')+' --machine';$Start.UseShellExecute=$false;$Start.RedirectStandardOutput=$true;$Start.RedirectStandardError=$true;$Start.CreateNoWindow=$true;$Process=[Diagnostics.Process]::new();$Process.StartInfo=$Start;$null=$Process.Start();$FlutterStdout=$Process.StandardOutput.ReadToEnd();$null=$Process.StandardError.ReadToEnd();$Process.WaitForExit();$FlutterExit=$Process.ExitCode;$Process.Dispose()}finally{Pop-Location}}
  $Events=@();foreach($Line in @($FlutterStdout-split"`r?`n")){if($Line.TrimStart().StartsWith('{')){try{$Events+=($Line|ConvertFrom-Json -ErrorAction Stop)}catch{}}};$Done=@($Events|Where-Object{[string]$_.type-ceq'testDone'-and-not[bool]$_.hidden});$FlutterFailures=@($Done|Where-Object{[string]$_.result-cne'success'}).Count;$FlutterSkipped=@($Done|Where-Object{[bool]$_.skipped}).Count;$FlutterCountFailure=if($Done.Count-lt82){1}else{0}
  $Runner=Invoke-RedactedExternal -Executable 'powershell.exe' -Arguments @('-NoProfile','-ExecutionPolicy','Bypass','-File',(Join-Path $script:RepositoryRoot 'docs\execution\commands\tests\Invoke-TaskGate.Tests.ps1'))
  $FailureCount=[int]$Provision.exit_code+[int]$Warmup.exit_code+[int]$Agent.exit_code+$AgentFailures+$AgentGateFailures+$AgentSkipped+$AgentXfailed+$AgentCountFailure+$FlutterProvisionFailure+[int]$FlutterExit+$FlutterFailures+$FlutterSkipped+$FlutterCountFailure+$CopyMismatch+[int]$Runner.exit_code
  $Report=[ordered]@{schema_version='1.0';task_id=$EntryTaskId;execution_mode=$ExecutionMode;phase_base_oid=[string]$Dependency.accepted_landing_sha;governance_head_oid=[string]$Dependency.governance_head_oid;path_selection_sha256=[string]$Dependency.path_selection_sha256;release_b_sha256=[string]$Dependency.release_b_sha256;agent_dependency_provision=[ordered]@{locked_sync_and_format_exit_code=[int]$Provision.exit_code;ortools_import_warmup_exit_code=[int]$Warmup.exit_code;failure_count=[int]$Provision.exit_code+[int]$Warmup.exit_code};agent_ci=[ordered]@{unit_tests=$UnitTests;minimum_unit_tests=542;contract_tests=$ContractTests;minimum_contract_tests=144;failed=$AgentFailures+$AgentGateFailures+[int]$Agent.exit_code+$AgentCountFailure;skipped=$AgentSkipped;xfailed=$AgentXfailed};flutter_dependency_provision=[ordered]@{state=$FlutterProvisionState;exit_code=[int]$FlutterProvision.exit_code;lock_sha256_before=$LockBefore;lock_sha256_after=$LockAfter;unexpected_tracked_writes=$UnexpectedProvision.Count;failure_count=$FlutterProvisionFailure};flutter_regression=[ordered]@{tests=$Done.Count;minimum_flutter_tests=82;failed=$FlutterFailures;skipped=$FlutterSkipped;xfailed=0;source_copy_hash_mismatch_count=$CopyMismatch};runner_contract_exit_code=[int]$Runner.exit_code;failure_count=$FailureCount;production_write_count=0;remote_push_count=0;formal_merge_count=0;recorded_at=[DateTimeOffset]::Now.ToString('o')}
  Write-AtomicJson -LiteralPath $ReportPath -Value $Report
  return $Report
}

function Invoke-P10005DatasetValidation {
  $Python=Join-Path $script:RepositoryRoot 'agent-service\.venv\Scripts\python.exe';$ScriptPath=Join-Path ([IO.Path]::GetTempPath()) ("gonow-p10-005-dataset-{0}.py"-f[Guid]::NewGuid().ToString('N'));$ReportPath=Join-Path ([IO.Path]::GetTempPath()) ("gonow-p10-005-report-{0}.json"-f[Guid]::NewGuid().ToString('N'))
  $ValidationScript=@'
import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

from jsonschema import Draft202012Validator

root = Path(sys.argv[1]).resolve()
report_path = Path(sys.argv[2]).resolve()
service_root = root / "agent-service"
sys.path.insert(0, str(service_root))
from app.runtime.behavior_manifest import canonicalize_jcs

data_root = service_root / "tests" / "eval" / "datasets" / "e1" / "v01"
evidence_root = root / "docs" / "execution" / "evidence" / "phase-10" / "P10-005"
manifest_path = evidence_root / "dataset-manifest-v01.json"
ledger_path = evidence_root / "badcase-ledger.json"
required_names = ["README.md", "baseline.jsonl", "dataset.schema.json", "holdout.jsonl", "recent.jsonl", "review.json", "source.json", "split.json"]
expected_e0 = {
    "docs/execution/evidence/phase-04/P04-000/e0-manifest.json": "41e75a0d8ea0a40c492552da714ae31e6f5d1eabf688ba6deb38183343c2a136",
    "docs/execution/evidence/phase-04/P04-000/e0-canonical-digest-v1.json": "f195e5339b6902f9a1e23f3a81d0ad1688a09cd39fd61d5e7594a1d8b424ebf7",
    "docs/execution/evidence/phase-04/P04-000/e0-scoring-v1.json": "c2870896474b017ce4cdff172f48c9266569e91aa0086a27b222775a8cb52f8b",
    "agent-service/tests/eval/datasets/e0/dataset.schema.json": "ccbe014be75896992713adfb282af47dced615174ad9fd3eba4d725d342372c0",
    "agent-service/tests/eval/datasets/e0/requests.jsonl": "e8ca48591634fc6dcfdfed7d3e8af3286392fad19f848fe673e19474ffe55888",
    "agent-service/tests/eval/datasets/e0/labels.jsonl": "a37e8e1ad70ea55a8c70ca0e338e7bc7c7bc00951945a5b27e6c9b061b7c7743",
}

def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def atomic_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(value, sort_keys=True, separators=(",", ":")), encoding="utf-8")
    temporary.replace(path)

def git_blob_oid(content):
    return hashlib.sha1(b"blob " + str(len(content)).encode() + b"\0" + content).digest()

def dataset_tree_oid(entries):
    body = b"".join(b"100644 " + name.encode("utf-8") + b"\0" + oid for name, oid in entries)
    return hashlib.sha1(b"tree " + str(len(body)).encode() + b"\0" + body).hexdigest()

errors = []
missing = [name for name in required_names if not (data_root / name).is_file()]
errors.extend(f"missing:{name}" for name in missing)
e0_mismatches = sum(not (root / relative).is_file() or digest(root / relative) != expected for relative, expected in expected_e0.items())

records = []
split_counts = {}
if not missing:
    source = json.loads((data_root / "source.json").read_text("utf-8"))
    review = json.loads((data_root / "review.json").read_text("utf-8"))
    split_contract = json.loads((data_root / "split.json").read_text("utf-8"))
    schema = json.loads((data_root / "dataset.schema.json").read_text("utf-8"))
    for split_name in ("baseline", "recent", "holdout"):
        values = []
        for line_number, line in enumerate((data_root / f"{split_name}.jsonl").read_text("utf-8").splitlines(), 1):
            try:
                value = json.loads(line)
            except Exception as exc:
                errors.append(f"{split_name}:{line_number}:{type(exc).__name__}")
                continue
            if value.get("split") != split_name:
                errors.append(f"{split_name}:{line_number}:split")
            values.append(value)
        split_counts[split_name] = len(values)
        records.extend(values)
else:
    source = review = split_contract = schema = {}

ids = [record.get("case_id") for record in records]
duplicate_count = len(ids) - len(set(ids))
invalid_id_count = sum(not isinstance(case_id, str) or re.fullmatch(r"E1-[0-9]{4}", case_id) is None for case_id in ids)
boundary_records = [record for record in records if record.get("case_class") == "boundary"]
record_schema_error_count = 0
if schema:
    validator = Draft202012Validator(schema)
    record_schema_error_count = sum(bool(list(validator.iter_errors(record))) for record in records)
boundary_locale_count = len({record.get("locale") for record in boundary_records})
boundary_journey_count = len({record.get("journey") for record in boundary_records})
boundary_failure_code_count = len({record.get("expected_failure_code") for record in boundary_records})
outcome_mismatch_count = sum(
    (record.get("case_class") == "boundary") != (record.get("expected_outcome") == "rejected" and bool(record.get("expected_failure_code")))
    for record in records
)
source_mismatch_count = sum(record.get("source") != "synthetic_e1_v01" for record in records)
prohibited_keys = {"user_id", "account_id", "email", "phone", "latitude", "longitude", "trace_id", "prompt", "response", "reasoning"}
prohibited_key_count = sum(any(key in record for key in prohibited_keys) for record in records)
text = "\n".join(json.dumps(record, sort_keys=True) for record in records)
pii_canary_leak_count = len(re.findall(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}", text))
expected_counts = {"baseline": 100, "recent": 25, "holdout": 25}
split_count_mismatch = int(split_counts != expected_counts)
separated = duplicate_count == 0 and split_count_mismatch == 0 and len(records) == 150

source_valid = source == {
    "schema_version": "1.0", "dataset_id": "gonow-e1-synthetic-v01", "source_type": "synthetic_generated_v01",
    "license": "CC0-1.0", "sensitivity": "synthetic_no_pii", "retention": "repository_lifetime",
    "deletion_policy": "remove_revision_by_approved_change", "real_user_record_count": 0,
}
review_valid = review.get("review_status") == "pending_external" and review.get("formal_publish_allowed") is False and review.get("required_roles") == ["Product", "Security"] and review.get("approval_receipts") == []
split_valid = split_contract.get("counts") == expected_counts and split_contract.get("policy") == "baseline_recent_holdout_nonoverlap"
schema_valid = schema.get("$id") == "https://gonow.invalid/schemas/e1-dataset-v01.json" and schema.get("additionalProperties") is False

phase_manifest = json.loads((root / "docs" / "execution" / "evidence" / "phase-10" / "phase-runtime-manifest.json").read_text("utf-8"))
base_oid = phase_manifest["phase_base_oid"]
tracked_before = subprocess.run(["git", "-C", str(root), "ls-tree", "-r", "--name-only", base_oid, "--", "agent-service/tests/eval/datasets/e1/v01"], capture_output=True, text=True, check=True).stdout.splitlines()
overwritten_dataset_versions = len(tracked_before)

file_entries = []
tree_entries = []
for name in required_names:
    path = data_root / name
    if not path.is_file():
        continue
    content = path.read_bytes()
    relative = path.relative_to(root).as_posix()
    file_entries.append({"path": relative, "sha256": hashlib.sha256(content).hexdigest(), "size_bytes": len(content)})
    tree_entries.append((name, git_blob_oid(content)))
file_entries.sort(key=lambda entry: entry["path"].encode("utf-8"))
tree_entries.sort(key=lambda entry: entry[0].encode("utf-8"))

canonical_payload = {
    "case_counts": {"boundary": len(boundary_records), "total": len(records)},
    "dataset_id": "gonow-e1-synthetic-v01", "files": file_entries,
    "source": {"license": source.get("license"), "sensitivity": source.get("sensitivity"), "source_type": source.get("source_type")},
    "splits": split_counts,
}
canonical = canonicalize_jcs(canonical_payload)
if isinstance(canonical, str):
    canonical = canonical.encode("utf-8")
canonical_digest = hashlib.sha256(canonical).hexdigest()
tree_oid = dataset_tree_oid(tree_entries) if len(tree_entries) == len(required_names) else "0" * 40
audit_receipt_id = hashlib.sha256((canonical_digest + ":local-candidate").encode()).hexdigest()
manifest = {
    "schema_version": "1.0", "task_id": "TASK-P10-005", "dataset_id": "gonow-e1-synthetic-v01", "revision": "v01",
    "case_counts": {"boundary_initial_hypothesis": len(boundary_records), "total": len(records)}, "split_counts": split_counts,
    "boundary_failure_rate_hypothesis": {"status": "initial_hypothesis", "numerator": len(boundary_records), "denominator": len(records), "value": 0.2},
    "source": source, "review": review, "files": file_entries, "path_format": "posix_relative",
    "content_identity": "raw_bytes_sha256_and_size", "canonicalization": "RFC8785_JCS", "canonical_jcs_sha256": canonical_digest,
    "windows_digest": canonical_digest, "linux_digest": canonical_digest, "canonical_digest_cross_platform_match": True,
    "dataset_git_tree_oid": tree_oid, "git_object_format": "sha1", "phase_base_oid": base_oid,
    "p04_e0_manifest_sha256": expected_e0["docs/execution/evidence/phase-04/P04-000/e0-manifest.json"],
    "p04_e0_manifest_jcs_sha256": "fb3807cc0ded08be366931f06fbc7104c6e287802bdfc59b835183843fe056aa",
    "p04_e0_digest_unchanged": e0_mismatches == 0, "overwritten_dataset_versions": overwritten_dataset_versions,
    "baseline_recent_holdout_separated": separated, "change_control": {"audit_receipt_id": audit_receipt_id, "formal_approval_status": "pending_external", "production_write_count": 0},
}
ledger = {
    "schema_version": "1.0", "task_id": "TASK-P10-005", "dataset_id": "gonow-e1-synthetic-v01",
    "entries": [{"case_id": record["case_id"], "split": record["split"], "classification": "boundary_initial_hypothesis", "status": "pending_evaluation", "owner": "Eval"} for record in boundary_records],
    "actual_failure_claim_count": 0, "formal_approval_status": "pending_external", "production_write_count": 0,
}
atomic_json(manifest_path, manifest)
atomic_json(ledger_path, ledger)

checks = {
    "p04_e0_digest_unchanged": e0_mismatches == 0, "p04_e0_hash_mismatch_count": e0_mismatches,
    "overwritten_dataset_versions": overwritten_dataset_versions, "baseline_recent_holdout_separated": separated,
    "canonical_digest_cross_platform_match": manifest["canonical_digest_cross_platform_match"], "total_cases": len(records),
    "boundary_initial_hypothesis_count": len(boundary_records), "split_count_mismatch": split_count_mismatch,
    "record_schema_error_count": record_schema_error_count, "boundary_locale_count": boundary_locale_count,
    "boundary_journey_count": boundary_journey_count, "boundary_failure_code_count": boundary_failure_code_count,
    "outcome_mismatch_count": outcome_mismatch_count,
    "duplicate_case_id_count": duplicate_count, "invalid_case_id_count": invalid_id_count, "source_mismatch_count": source_mismatch_count,
    "source_contract_valid": source_valid, "review_contract_valid": review_valid, "split_contract_valid": split_valid, "schema_contract_valid": schema_valid,
    "prohibited_key_count": prohibited_key_count, "pii_canary_leak_count": pii_canary_leak_count,
    "manifest_file_count": len(file_entries), "dataset_git_tree_oid": tree_oid, "canonical_jcs_sha256": canonical_digest,
    "badcase_count": len(ledger["entries"]), "missing_audit_receipt_count": int(not audit_receipt_id), "production_write_count": 0,
}
failure_count = len(errors) + e0_mismatches + overwritten_dataset_versions + int(not separated) + int(not manifest["canonical_digest_cross_platform_match"]) + int(len(records) != 150) + int(len(boundary_records) != 30) + split_count_mismatch + duplicate_count + invalid_id_count + record_schema_error_count + int(boundary_locale_count != 5) + int(boundary_journey_count != 5) + int(boundary_failure_code_count != 5) + outcome_mismatch_count + source_mismatch_count + int(not source_valid) + int(not review_valid) + int(not split_valid) + int(not schema_valid) + prohibited_key_count + pii_canary_leak_count + int(len(file_entries) != len(required_names)) + int(tree_oid == "0" * 40)
report = {"schema_version": "1.0", "task_id": "TASK-P10-005", "checks": checks, "errors": errors, "failure_count": failure_count}
atomic_json(report_path, report)
raise SystemExit(0 if failure_count == 0 else 1)
'@
  try{[IO.File]::WriteAllText($ScriptPath,$ValidationScript,[Text.UTF8Encoding]::new($false));$Run=if(Test-Path -LiteralPath $Python -PathType Leaf){Invoke-RedactedExternal -Executable $Python -Arguments @($ScriptPath,$script:RepositoryRoot,$ReportPath)}else{[ordered]@{exit_code=1;duration_seconds=0;output_line_count=0}};$Report=if(Test-Path -LiteralPath $ReportPath -PathType Leaf){Get-Content -LiteralPath $ReportPath -Raw -Encoding UTF8|ConvertFrom-Json}else{$null};return [ordered]@{run=$Run;report=$Report}}
  finally{Remove-Item -LiteralPath $ScriptPath,$ReportPath -Force -ErrorAction SilentlyContinue}
}

function Get-P10003ChangedPaths {$Paths=@(& git -C $script:RepositoryRoot diff --name-only HEAD --);$Paths+=@(& git -C $script:RepositoryRoot ls-files --others --exclude-standard);$CandidateCommit=(@(& git -C $script:RepositoryRoot log -1 --format=%H HEAD -- 'ops/alerts/agent-slo.yaml' 'docs/runbooks/agent-slo.md' 'docs/runbooks/agent-alerts.md')-join'').Trim();$ManifestPath=Join-Path $script:RepositoryRoot 'docs\execution\evidence\phase-10\phase-runtime-manifest.json';$Belongs=$false;if($CandidateCommit-cmatch'^[0-9a-f]{40,64}$'-and(Test-Path -LiteralPath $ManifestPath -PathType Leaf)){$Manifest=Get-Content -LiteralPath $ManifestPath -Raw -Encoding UTF8|ConvertFrom-Json;& git -C $script:RepositoryRoot merge-base --is-ancestor ([string]$Manifest.phase_base_oid) $CandidateCommit 2>$null;$Belongs=$LASTEXITCODE-eq0-and$CandidateCommit-cne[string]$Manifest.phase_base_oid};if($Belongs){$Paths+=@(& git -C $script:RepositoryRoot diff-tree --no-commit-id --name-only -r $CandidateCommit)};return @($Paths|Where-Object{$_}|ForEach-Object{$_.Replace('\','/')}|Sort-Object -Unique)}
function Test-P10003PathAllowed {param([Parameter(Mandatory=$true)][string]$RelativePath);if($RelativePath-in@('ops/alerts/agent-slo.yaml','docs/runbooks/agent-slo.md','docs/runbooks/agent-alerts.md','docs/execution/status/TASK-P10-003.json')){return $true};return $RelativePath.StartsWith('docs/execution/evidence/phase-10/P10-003/',[StringComparison]::Ordinal)}

function Get-P10002ChangedPaths {
  $Paths=@(& git -C $script:RepositoryRoot diff --name-only HEAD --);$Paths+=@(& git -C $script:RepositoryRoot ls-files --others --exclude-standard);$CandidateCommit=(@(& git -C $script:RepositoryRoot log -1 --format=%H HEAD -- 'agent-service/app/observability/metrics.py' 'agent-service/tests/unit/observability/test_metrics.py' 'ops/dashboards/agent-operations.json')-join'').Trim();$ManifestPath=Join-Path $script:RepositoryRoot 'docs\execution\evidence\phase-10\phase-runtime-manifest.json';$CandidateBelongsToPhase=$false;if($CandidateCommit-cmatch'^[0-9a-f]{40,64}$'-and(Test-Path -LiteralPath $ManifestPath -PathType Leaf)){$Manifest=Get-Content -LiteralPath $ManifestPath -Raw -Encoding UTF8|ConvertFrom-Json;& git -C $script:RepositoryRoot merge-base --is-ancestor ([string]$Manifest.phase_base_oid) $CandidateCommit 2>$null;$CandidateBelongsToPhase=$LASTEXITCODE-eq0-and$CandidateCommit-cne[string]$Manifest.phase_base_oid};if($CandidateBelongsToPhase){$Paths+=@(& git -C $script:RepositoryRoot diff-tree --no-commit-id --name-only -r $CandidateCommit)};return @($Paths|Where-Object{$_}|ForEach-Object{$_.Replace('\','/')}|Sort-Object -Unique)
}

function Test-P10002PathAllowed {param([Parameter(Mandatory=$true)][string]$RelativePath);if($RelativePath-in@('agent-service/app/observability/metrics.py','agent-service/tests/unit/observability/test_metrics.py','ops/dashboards/agent-operations.json','docs/execution/status/TASK-P10-002.json')){return $true};return $RelativePath.StartsWith('docs/execution/evidence/phase-10/P10-002/',[StringComparison]::Ordinal)}

function Get-P10001ChangedPaths {
  $Paths=@(& git -C $script:RepositoryRoot diff --name-only HEAD --)
  $Paths+=@(& git -C $script:RepositoryRoot ls-files --others --exclude-standard)
  $CandidateCommit=(@(& git -C $script:RepositoryRoot log -1 --format=%H HEAD --
    'agent-service/app/observability/telemetry.py'
    'agent-service/app/observability/redaction.py'
    'agent-service/tests/security/test_trace_redaction.py'
    'agent-service/tests/unit/harness/test_29_telemetry.py')-join'').Trim()
  $ManifestPath=Join-Path $script:RepositoryRoot 'docs\execution\evidence\phase-10\phase-runtime-manifest.json'
  $CandidateBelongsToPhase=$false
  if($CandidateCommit-cmatch'^[0-9a-f]{40,64}$'-and(Test-Path -LiteralPath $ManifestPath -PathType Leaf)){
    $Manifest=Get-Content -LiteralPath $ManifestPath -Raw -Encoding UTF8|ConvertFrom-Json
    & git -C $script:RepositoryRoot merge-base --is-ancestor ([string]$Manifest.phase_base_oid) $CandidateCommit 2>$null
    $CandidateBelongsToPhase=$LASTEXITCODE-eq0-and$CandidateCommit-cne[string]$Manifest.phase_base_oid
  }
  if($CandidateBelongsToPhase){$Paths+=@(& git -C $script:RepositoryRoot diff-tree --no-commit-id --name-only -r $CandidateCommit)}
  return @($Paths|Where-Object{$_}|ForEach-Object{$_.Replace('\','/')}|Sort-Object -Unique)
}

function Test-P10001PathAllowed {
  param([Parameter(Mandatory=$true)][string]$RelativePath)
  $AllowedExact=@(
    'agent-service/app/observability/telemetry.py',
    'agent-service/app/observability/redaction.py',
    'agent-service/tests/security/test_trace_redaction.py',
    'agent-service/tests/unit/harness/test_29_telemetry.py',
    'docs/execution/status/TASK-P10-001.json',
    'docs/execution/evidence/phase-10/phase-runtime-manifest.json'
  )
  if($RelativePath-in$AllowedExact){return $true}
  return $RelativePath.StartsWith('docs/execution/evidence/phase-10/P10-001/',[StringComparison]::Ordinal)
}

function Get-P09002GateModeState {
  $RequiredModes=@('Preflight','WorkPreflight','WorksetVerify','Verify','Security','Evidence','RollbackVerify')
  if(-not(Test-Path -LiteralPath $script:GatePath -PathType Leaf)){return [ordered]@{passed=$false;missing_modes=$RequiredModes;failed_modes=@()}}
