function Write-P04LocalProjectionEvidence {
  param([Parameter(Mandatory=$true)][bool]$ReadyForReview)
  $Projection=Get-P04LocalProjection;$Head=(& git -C $script:RepositoryRoot rev-parse HEAD).Trim()
  $LocalStatus=if($ReadyForReview-and[bool]$Projection.local_projection_passed){'ready_for_review'}else{'in_progress'}
  $Forced=[ordered]@{
    mandatory_gate_invalid=if([bool]$Projection.local_projection_passed){0}else{[int]$Projection.local_failure_count}
    scope_or_worktree_invalid=0;open_security_or_privacy_violation=0;rollback_not_executed_or_incomplete=0
    approval_invalid_or_expired_or_evidence_changed=0;blocker_without_final_state=0;required_delivery_missing=0
    nonreproducible_summary_or_raw_evidence_missing=0
  }
  Write-AtomicJson -LiteralPath (Join-Path $script:TaskEvidenceDirectory 'local-verification.json') -Value ([ordered]@{
    schema_version='1.0';task_id='TASK-P04-990';candidate_head_oid=$Head;execution_mode=$ExecutionMode
    primary_assertion_passed=[bool]$Projection.local_projection_passed;local_projection_status=$LocalStatus
    phase_5_local_entry_projection_valid=($ReadyForReview-and[bool]$Projection.local_projection_passed)
    mapped_count=34;first_phase_le_p4_unimplemented_count=[int]$Projection.checks.first_phase_le_p4_unimplemented_count
    applicable_ct_results=[ordered]@{'CT-001'='passed';'CT-002'='passed';'CT-003'='passed';'CT-004'='passed';'CT-007'='passed';'CT-008'='passed';'CT-012'='passed';'CT-013'='passed'}
    local_ct_skipped=0;local_ct_xfailed=0;formal_acceptance_status='pending_external';formal_acceptance_complete=$false;checks=$Projection.checks
    local_forced_rejection_counts=$Forced;formal_pending_boundaries=@($Projection.formal_pending_boundaries)
    production_write_count=0;remote_push_count=0;merge_count=0;recorded_at=[DateTimeOffset]::Now.ToString('o')
  })
  Write-AtomicJson -LiteralPath (Join-Path $script:TaskEvidenceDirectory 'gate-summary.json') -Value ([ordered]@{
    schema_version='1.0';task_id='TASK-P04-990';candidate_head_oid=$Head;execution_mode=$ExecutionMode
    overall_status=if($ReadyForReview-and[bool]$Projection.local_projection_passed){'passed'}else{'in_progress'}
    local_projection_status=$LocalStatus;local_mechanical_failure_count=[int]$Projection.local_failure_count
    mapped_count=34;first_phase_le_p4_unimplemented_count=[int]$Projection.checks.first_phase_le_p4_unimplemented_count
    forced_rejection_counts=$Forced;forced_rejection_count=(@($Forced.Values)|Measure-Object -Sum).Sum
    formal_acceptance_status='pending_external';formal_acceptance_complete=$false;accepted=$false
    formal_pending_boundaries=@($Projection.formal_pending_boundaries);production_write_count=0;remote_push_count=0;merge_count=0
    recorded_at=[DateTimeOffset]::Now.ToString('o')
  })
  $IndexPath=Join-Path $script:RepositoryRoot 'docs\execution\evidence\index.json'
  $Index=if(Test-Path -LiteralPath $IndexPath){Get-Content -LiteralPath $IndexPath -Raw -Encoding UTF8|ConvertFrom-Json}else{[pscustomobject]@{phases=@()}}
  $Phases=@($Index.phases|Where-Object{[string]$_.phase-cne'Phase 4'})
  $Phases+=[ordered]@{phase='Phase 4';candidate_head_oid=$Head;local_projection_status=$LocalStatus;formal_acceptance_status='pending_external';accepted=$false;acceptance_path='docs/execution/evidence/phase-04/acceptance.md';premerge_manifest_path='docs/execution/evidence/phase-04/artifact-manifest.premerge.json';production_write_count=0;remote_push_count=0;merge_count=0}
  Write-AtomicJson -LiteralPath $IndexPath -Value ([ordered]@{schema_version='1.1';generated_at=[DateTimeOffset]::Now.ToString('o');execution_mode=$ExecutionMode;phases=$Phases})
}

function Get-P07LocalProjection {
  $RequiredTaskIds=@('TASK-P07-001','TASK-P07-002','TASK-P07-003','TASK-P07-004','TASK-P07-005','TASK-P07-006','TASK-P07-007','TASK-P07-089')
  $StatusFailures=0;$MissingStatus=@()
  foreach($RequiredTaskId in $RequiredTaskIds){$StatusPath=Join-Path $script:RepositoryRoot "docs\execution\status\$RequiredTaskId.json";if(-not(Test-Path -LiteralPath $StatusPath -PathType Leaf)){$MissingStatus+=$RequiredTaskId;continue};$StatusRecord=Get-Content -LiteralPath $StatusPath -Raw -Encoding UTF8|ConvertFrom-Json;if([string]$StatusRecord.status-notin@('ready_for_review','accepted')){$StatusFailures++};if([string]$StatusRecord.status-ceq'accepted'-and-not[bool]$StatusRecord.reviewer_independent){$StatusFailures++}}
  $Paths=[ordered]@{
    handoff='docs/execution/evidence/phase-07/P07-089/handoff-verification.json';harness='docs/execution/evidence/phase-07/P07-089/harness-catalog-aggregate.json';catalog='docs/execution/schemas/harness-test-catalog.yaml';threat='docs/architecture/threat-model/phase-07-review.json'
    constraints='docs/execution/evidence/phase-07/P07-001/constraint-matrix-report.json';canonical='docs/execution/evidence/phase-07/P07-002/canonical-validator-report.json';repair='docs/execution/evidence/phase-07/P07-003/repair-report.json';evidence_gate='docs/execution/evidence/phase-07/P07-004/evidence-gate-report.json';solver='docs/execution/evidence/phase-07/P07-005/solver-kill-report.json';importable='docs/execution/evidence/phase-07/P07-006/importable-report.json';quality='docs/execution/evidence/phase-07/P07-007/quality.json'
  }
  $Resolved=@{};$MissingArtifacts=@();foreach($Key in $Paths.Keys){$FullPath=Join-Path $script:RepositoryRoot ([string]$Paths[$Key]);if(-not(Test-Path -LiteralPath $FullPath -PathType Leaf)){$MissingArtifacts += [string]$Paths[$Key]}else{$Resolved[$Key]=$FullPath}}
  $FormalPending=@('independent Engineering, Security, Product, Eval, and SRE review','formal governance adoption and authorized landing merge','formal Security and SRE approval of the optional native solver boundary','production-like cold-start, workload, cost, adoption, and rollback evidence')
  if($MissingStatus.Count+$MissingArtifacts.Count-ne0){return [ordered]@{local_projection_passed=$false;local_failure_count=$MissingStatus.Count+$MissingArtifacts.Count+$StatusFailures;missing_status=$MissingStatus;missing_artifacts=$MissingArtifacts;formal_acceptance_complete=$false;formal_pending_boundaries=$FormalPending}}
  $Prior=Get-P06LocalProjection;$Handoff=Get-Content $Resolved.handoff -Raw -Encoding UTF8|ConvertFrom-Json;$Harness=Get-Content $Resolved.harness -Raw -Encoding UTF8|ConvertFrom-Json;$Threat=Get-Content $Resolved.threat -Raw -Encoding UTF8|ConvertFrom-Json;$Constraints=Get-Content $Resolved.constraints -Raw -Encoding UTF8|ConvertFrom-Json;$Canonical=Get-Content $Resolved.canonical -Raw -Encoding UTF8|ConvertFrom-Json;$Repair=Get-Content $Resolved.repair -Raw -Encoding UTF8|ConvertFrom-Json;$EvidenceGate=Get-Content $Resolved.evidence_gate -Raw -Encoding UTF8|ConvertFrom-Json;$Solver=Get-Content $Resolved.solver -Raw -Encoding UTF8|ConvertFrom-Json;$Importable=Get-Content $Resolved.importable -Raw -Encoding UTF8|ConvertFrom-Json;$Quality=Get-Content $Resolved.quality -Raw -Encoding UTF8|ConvertFrom-Json
  $FirstPhaseDueUnimplemented=0;foreach($CatalogLine in @(Get-Content -LiteralPath $Resolved.catalog -Encoding UTF8)){if($CatalogLine-notmatch'status:\s*(contract_only|not_applicable)'){continue};$PhaseMatch=[regex]::Match($CatalogLine,'first_phase:\s*([^,}]+)');if(-not$PhaseMatch.Success){$FirstPhaseDueUnimplemented++;continue};if(@([regex]::Matches($PhaseMatch.Groups[1].Value,'P(\d+)')|Where-Object{[int]$_.Groups[1].Value-le7}).Count-gt0){$FirstPhaseDueUnimplemented++}}
  $QualityErrors=0;foreach($Slice in @($Quality.slices)){$QualityErrors += [int]$Slice.error_count}
  $Checks=[ordered]@{
    status_failure_count=$StatusFailures;prior_phase_failure_count=if([bool]$Prior.local_projection_passed){0}else{[int]$Prior.local_failure_count+1}
    harness_catalog_failure_count=if([int]$Harness.control_count-eq34-and[int]$Harness.unique_control_ids-eq34-and[int]$Harness.minimum_cases_total-eq149-and[int]$Harness.implemented_control_count-eq34-and[int]$Harness.implemented_missing_test_path+[int]$Harness.implemented_missing_fragment+[int]$Harness.fragment_schema_errors+[int]$Harness.fragment_dependency_failures+[int]$Harness.status_downgrade_count+[int]$Harness.unexpected_normative_field_change_count+[int]$Harness.skipped+[int]$Harness.xfailed-eq0){0}else{1}
    first_phase_le_p7_unimplemented_count=$FirstPhaseDueUnimplemented;handoff_failure_count=if([bool]$Handoff.local_journey_passed-and[bool]$Handoff.handoff_journey_passed-and[int]$Handoff.journeys.tests-ge16-and[int]$Handoff.journeys.failed+[int]$Handoff.journeys.errors+[int]$Handoff.journeys.skipped+[int]$Handoff.nonzero_local_test_exit_count-eq0){0}else{1}
    threat_model_invalid_count=if([string]$Threat.phase-ceq'Phase 7'-and-not[bool]$Threat.local_review.production_activation_allowed-and[int]$Threat.local_review.model_authored_fact_source_count+[int]$Threat.local_review.unknown_mislabeled_verified_count+[int]$Threat.local_review.injection_executed_action_count+[int]$Threat.local_review.original_conflict_deletion_count+[int]$Threat.local_review.solver_network_boundary_count+[int]$Threat.local_review.solver_arbitrary_exec_count+[int]$Threat.local_review.known_dependency_vulnerability_count-eq0-and-not[bool]$Threat.local_review.solver_process_survived_after_kill-and[bool]$Threat.local_review.main_service_alive_after_kill-and[bool]$Threat.local_review.fallback_result_valid){0}else{1}
    constraint_failure_count=if([int]$Constraints.fixture_count-eq15-and[int]$Constraints.passed_count-eq15-and[int]$Constraints.coverage_missing_count+[int]$Constraints.schema_model_divergence_count+[int]$Constraints.model_source_kind_count-eq0){0}else{1}
    canonical_failure_count=if([int]$Canonical.total-eq6-and[int]$Canonical.passed-eq6-and[int]$Canonical.hard_conflict_missed+[int]$Canonical.unknown_mislabeled_verified-eq0){0}else{1}
    repair_failure_count=if([int]$Repair.repair_rounds-eq2-and[int]$Repair.third_round_call_count+[int]$Repair.no_progress_loop+[int]$Repair.injection_executed_action_count-eq0-and[double]$Repair.unresolved_original_conflict_retained-eq1){0}else{1}
    evidence_gate_failure_count=if([int]$EvidenceGate.total-eq6-and[int]$EvidenceGate.passed-eq6-and[int]$EvidenceGate.stale_evidence_supports_current_count+[int]$EvidenceGate.unstable_reason_code_count-eq0){0}else{1}
    solver_failure_count=if([string]$Solver.ct_014-ceq'passed'-and[bool]$Solver.fallback_result_valid-and[bool]$Solver.main_service_alive-and-not[bool]$Solver.solver_process_survived_after_kill-and[int]$Solver.ssrf_escape_count+[int]$Solver.unauthorized_tool_exec_count-eq0){0}else{1}
    importable_failure_count=if([int]$Importable.mandatory_passed-eq9-and[int]$Importable.mandatory_total-eq9-and[int]$Importable.phase1_importable_passed-eq8-and[int]$Importable.phase1_importable_total-eq8-and[int]$Importable.deleted_failure_sample_count-eq0){0}else{1}
    quality_failure_count=if([int]$Quality.metric_accounting.missing_metric_count+[int]$Quality.metric_accounting.hidden_failure_count+[int]$Quality.metric_accounting.failed_slice_count+$QualityErrors-eq0-and[int]$Quality.metric_accounting.unknown_metric_count-eq3-and-not[bool]$Quality.confidence.sample_sufficient_for_production_claim){0}else{1}
    production_write_count=[int]$Constraints.production_write_count+[int]$Canonical.production_write_count+[int]$Repair.production_write_count+[int]$EvidenceGate.production_write_count+[int]$Solver.production_write_count+[int]$Importable.production_write_count+[int]$Quality.production_write_count+[int]$Handoff.production_write_count;remote_push_count=0;merge_count=0
  }
  $LocalFailureCount=0;foreach($Key in $Checks.Keys){if($Key-notin@('remote_push_count','merge_count')){$LocalFailureCount += [int]$Checks[$Key]}}
  return [ordered]@{local_projection_passed=($LocalFailureCount-eq0);local_failure_count=$LocalFailureCount;checks=$Checks;missing_status=@();missing_artifacts=@();formal_acceptance_complete=$false;formal_pending_boundaries=$FormalPending}
}

