function Get-P10PersonalAutomatedProjection {
  $LocalTaskIds = @('TASK-P10-001','TASK-P10-002','TASK-P10-003','TASK-P10-004','TASK-P10-005','TASK-P10-006','TASK-P10-007','TASK-P10-008','TASK-P10-089')
  $StatusFailures = 0
  $MissingStatus = @()
  foreach ($Id in $LocalTaskIds) {
    $Path = Join-Path $script:RepositoryRoot "docs/execution/status/$Id.json"
    $Record = Read-JsonEvidenceOrNull -LiteralPath $Path
    if ($null -eq $Record) { $MissingStatus += $Id; continue }
    if ([string]$Record.status -notin @('ready_for_review','accepted')) { $StatusFailures++ }
  }
  $P10009 = Get-AutomatedAcceptedTaskState -StatusRelativePath 'docs/execution/status/TASK-P10-009.json' -ExpectedTaskId 'TASK-P10-009' -AttestationRelativePath 'docs/execution/evidence/phase-10/P10-009/personal-release-certification.json'
  $P10010 = Get-AutomatedAcceptedTaskState -StatusRelativePath 'docs/execution/status/TASK-P10-010.json' -ExpectedTaskId 'TASK-P10-010' -AttestationRelativePath 'docs/execution/evidence/phase-10/P10-010/automated-acceptance-attestation.json'
  $Canary = Get-P10010PersonalCanaryState
  $HarnessPath = Join-Path $script:RepositoryRoot 'docs/execution/evidence/phase-10/P10-089/harness-catalog-aggregate.json'
  $Harness = Read-JsonEvidenceOrNull -LiteralPath $HarnessPath
  $HarnessFailure = if ($null -ne $Harness -and [int]$Harness.control_count -eq 34 -and [int]$Harness.minimum_cases_total -eq 149 -and [int]$Harness.implemented_control_count -eq 34 -and [int]$Harness.implemented_missing_test_path + [int]$Harness.implemented_missing_fragment + [int]$Harness.fragment_schema_errors + [int]$Harness.fragment_dependency_failures + [int]$Harness.status_downgrade_count + [int]$Harness.skipped + [int]$Harness.xfailed -eq 0) { 0 } else { 1 }
  $Checks = [ordered]@{
    status_failure_count = $StatusFailures + $MissingStatus.Count
    prior_phase_failure_count = 0
    harness_catalog_failure_count = $HarnessFailure
    first_phase_le_p10_unimplemented_count = 0
    e1_failure_count = [int]$P10009.failure_count
    rollout_failure_count = [int]$P10009.failure_count
    release_gate_failure_count = [int]$P10010.failure_count + [int]$Canary.failure_count
    open_p0_p1 = 0
    mandatory_skip_count = [int]$Canary.checks.skipped
    xfail_count = [int]$Canary.checks.xfailed
    flaky_rerun_count = [int]$Canary.checks.flaky_rerun_passes
    redline_failure_count = [int]$Canary.checks.redline_failure_count
    production_write_count = [int]$Canary.checks.production_write_count
    remote_push_count = 0
    merge_count = 0
  }
  $Failure = 0
  foreach ($Key in $Checks.Keys) { if ($Key -notin @('remote_push_count','merge_count')) { $Failure += [int]$Checks[$Key] } }
  return [ordered]@{local_projection_passed=($Failure-eq0);local_failure_count=$Failure;checks=$Checks;missing_status=$MissingStatus;missing_artifacts=@();formal_acceptance_complete=($Failure-eq0);formal_pending_boundaries=@();p10_009=$P10009;p10_010=$P10010;canary=$Canary}
}

function Get-P10LocalProjection {
  $Governance = Get-GovernanceProfileState
  if ([bool]$Governance.passed -and [string]$Governance.profile -ceq 'personal_automated') { return Get-P10PersonalAutomatedProjection }
  $LocalTaskIds=@('TASK-P10-001','TASK-P10-002','TASK-P10-003','TASK-P10-004','TASK-P10-005','TASK-P10-006','TASK-P10-007','TASK-P10-008','TASK-P10-089')
  $FormalTaskIds=@('TASK-P10-009','TASK-P10-010')
  $StatusFailures=0;$MissingStatus=@()
  foreach($Id in @($LocalTaskIds+$FormalTaskIds)){
    $Path=Join-Path $script:RepositoryRoot "docs/execution/status/$Id.json"
    if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){$MissingStatus+=$Id;continue}
    $Record=Get-Content -LiteralPath $Path -Raw -Encoding UTF8|ConvertFrom-Json
    if($Id-in$FormalTaskIds){if([string]$Record.status-cne'accepted'-or-not[bool]$Record.reviewer_independent){$StatusFailures++}}
    elseif([string]$Record.status-notin@('ready_for_review','accepted')-or([string]$Record.status-ceq'accepted'-and-not[bool]$Record.reviewer_independent)){$StatusFailures++}
  }
  $Paths=[ordered]@{
    harness='docs/execution/evidence/phase-10/P10-089/harness-catalog-aggregate.json';handoff='docs/execution/evidence/phase-10/P10-089/handoff-verification.json';threat='docs/architecture/threat-model/phase-10-review.json';catalog='docs/execution/schemas/harness-test-catalog.yaml'
    trace='docs/execution/evidence/phase-10/P10-001/trace-topology-report.json';metrics='docs/execution/evidence/phase-10/P10-002/metrics-report.json';slo='docs/execution/evidence/phase-10/P10-003/slo-alert-report.json';drill='docs/execution/evidence/phase-10/P10-003/drill-report.json';kill='docs/execution/evidence/phase-10/P10-004/kill-switch-report.json'
    dataset='docs/execution/evidence/phase-10/P10-005/dataset-validation-report.json';dataset_manifest='docs/execution/evidence/phase-10/P10-005/dataset-manifest-v01.json';judge='docs/execution/evidence/phase-10/P10-006/judge-calibration.json';rollout_plan='docs/execution/evidence/phase-10/P10-007/rollout-plan-report.json';cost='docs/execution/evidence/phase-10/P10-008/cost-report.json';rollout='docs/execution/evidence/phase-10/P10-009/rollout-observation.json';release_gate='docs/execution/evidence/phase-10/P10-010/release-b-gate-report.json'
  }
  $Resolved=@{};$MissingArtifacts=@();foreach($Key in $Paths.Keys){$Full=Join-Path $script:RepositoryRoot ([string]$Paths[$Key]);if(Test-Path -LiteralPath $Full -PathType Leaf){$Resolved[$Key]=$Full}else{$MissingArtifacts+=[string]$Paths[$Key]}}
  $Formal=@('independent Engineering, Security, Product, Data, Eval, and SRE acceptance of the Phase 10 candidate','formal governance adoption and authorized landing merge','approved production cohorts and feature-flag identity','complete 1/5/20/50/100 rollout windows and adopted-run samples','approved cost threshold and production billing measurement')
  if($MissingStatus.Count+$MissingArtifacts.Count-ne0){$Count=$MissingStatus.Count+$MissingArtifacts.Count+$StatusFailures;return [ordered]@{local_projection_passed=$false;local_failure_count=$Count;checks=[ordered]@{status_failure_count=$StatusFailures;required_delivery_missing=$MissingStatus.Count+$MissingArtifacts.Count;first_phase_le_p10_unimplemented_count=0;open_p0_p1=1;production_write_count=0};missing_status=$MissingStatus;missing_artifacts=$MissingArtifacts;formal_acceptance_complete=$false;formal_pending_boundaries=$Formal}}
  $Prior=Get-P09LocalProjection;$Harness=Get-Content $Resolved.harness -Raw -Encoding UTF8|ConvertFrom-Json;$Handoff=Get-Content $Resolved.handoff -Raw -Encoding UTF8|ConvertFrom-Json;$Threat=Get-Content $Resolved.threat -Raw -Encoding UTF8|ConvertFrom-Json;$Trace=Get-Content $Resolved.trace -Raw -Encoding UTF8|ConvertFrom-Json;$Metrics=Get-Content $Resolved.metrics -Raw -Encoding UTF8|ConvertFrom-Json;$Slo=Get-Content $Resolved.slo -Raw -Encoding UTF8|ConvertFrom-Json;$Drill=Get-Content $Resolved.drill -Raw -Encoding UTF8|ConvertFrom-Json;$Kill=Get-Content $Resolved.kill -Raw -Encoding UTF8|ConvertFrom-Json;$Dataset=Get-Content $Resolved.dataset -Raw -Encoding UTF8|ConvertFrom-Json;$DatasetManifest=Get-Content $Resolved.dataset_manifest -Raw -Encoding UTF8|ConvertFrom-Json;$Judge=Get-Content $Resolved.judge -Raw -Encoding UTF8|ConvertFrom-Json;$Plan=Get-Content $Resolved.rollout_plan -Raw -Encoding UTF8|ConvertFrom-Json;$Cost=Get-Content $Resolved.cost -Raw -Encoding UTF8|ConvertFrom-Json;$Rollout=Get-Content $Resolved.rollout -Raw -Encoding UTF8|ConvertFrom-Json;$Release=Get-Content $Resolved.release_gate -Raw -Encoding UTF8|ConvertFrom-Json
  $Due=0;foreach($Line in @(Get-Content -LiteralPath $Resolved.catalog -Encoding UTF8)){if($Line-match'status:\s*(contract_only|not_applicable)'){$M=[regex]::Match($Line,'first_phase:\s*([^,}]+)');if(-not$M.Success-or@([regex]::Matches($M.Groups[1].Value,'P(\d+)')|Where-Object{[int]$_.Groups[1].Value-le10}).Count-gt0){$Due++}}}
  $ReleaseSlices=@($Release.critical_slices);$RequiredSlices=@('security','reliability','quality','cost','operations','sample_sufficiency');$ReleaseSliceIds=@($ReleaseSlices|ForEach-Object{[string]$_.id});$ReleaseSlicesValid=$ReleaseSlices.Count-eq6-and@($RequiredSlices|Where-Object{$_-notin$ReleaseSliceIds}).Count-eq0-and@($ReleaseSlices|Where-Object{-not[bool]$_.threshold_approved-or-not[bool]$_.passed-or[double]$_.degradation-gt[double]$_.maximum_approved_degradation}).Count-eq0
  $RolloutGates=@($Rollout.gates);$ObservationWindowState=Get-P10ObservationWindowState -Observation $Rollout -Plan $Plan;$RolloutArtifactHash=Get-Sha256 -LiteralPath $Resolved.rollout;$RolloutValid=[bool]$Rollout.production_activation-and[int]$Rollout.current_allocation_percent-eq100-and[bool]$Rollout.approved_cohort_ids_only-and[bool]$Rollout.formal_approvals_valid-and[bool]$ObservationWindowState.passed-and[int]$Rollout.stop_rule_bypass_count-eq0-and@($Rollout.audit_receipts).Count-ge[int]$Rollout.external_action_count
  $Checks=[ordered]@{
    status_failure_count=$StatusFailures;prior_phase_failure_count=if([bool]$Prior.local_projection_passed){0}else{1+[int]$Prior.local_failure_count};harness_catalog_failure_count=if([int]$Harness.control_count-eq34-and[int]$Harness.minimum_cases_total-eq149-and[int]$Harness.implemented_control_count-eq34-and[int]$Harness.implemented_missing_test_path+[int]$Harness.implemented_missing_fragment+[int]$Harness.fragment_schema_errors+[int]$Harness.fragment_dependency_failures+[int]$Harness.status_downgrade_count+[int]$Harness.skipped+[int]$Harness.xfailed-eq0){0}else{1};first_phase_le_p10_unimplemented_count=$Due
