    trace_failure_count=if([int]$Trace.topology_stage_count-eq6-and[bool]$Trace.deterministic_parent_chain_test_passed-and[bool]$Trace.allowlist_rejection_test_passed-and[int]$Trace.canary_leak_count+[int]$Trace.raw_run_identifier_leak_count+[int]$Trace.failures+[int]$Trace.errors+[int]$Trace.skipped+[int]$Trace.xfailed-eq0){0}else{1};metrics_failure_count=if([int]$Metrics.domain_count-eq6-and[int]$Metrics.metric_count-ge12-and[int]$Metrics.metric_type_unit_owner_missing_count+[int]$Metrics.high_cardinality_label_accept_count+[int]$Metrics.failures+[int]$Metrics.errors+[int]$Metrics.skipped+[int]$Metrics.xfailed-eq0){0}else{1};slo_failure_count=if([int]$Slo.alert_count-eq5-and[int]$Slo.owner_missing_count+[int]$Slo.runbook_missing_count+[int]$Slo.test_missing_count-eq0-and[bool]$Drill.local_static_drill_passed-and[int]$Drill.fixture_passed_count-eq5){0}else{1};kill_switch_failure_count=if([int]$Kill.drill_scope_count-eq3-and[int]$Kill.new_agent_runs_after_drill-eq0-and[bool]$Kill.old_path_available-and[bool]$Kill.generation_cas_passed-and[bool]$Kill.authorization_passed-and[bool]$Kill.propagation_passed-and[bool]$Kill.audit_passed-and[bool]$Kill.rollback_passed-and[int]$Kill.failures+[int]$Kill.errors+[int]$Kill.skipped+[int]$Kill.xfailed-eq0){0}else{1}
    e1_failure_count=if([int]$Dataset.failure_count-eq0-and[int]$Dataset.checks.total_cases-eq150-and[bool]$Dataset.checks.p04_e0_digest_unchanged-and[bool]$Dataset.checks.canonical_digest_cross_platform_match-and[int]$Dataset.checks.p04_e0_hash_mismatch_count+[int]$Dataset.checks.duplicate_case_id_count+[int]$Dataset.checks.record_schema_error_count+[int]$Dataset.checks.pii_canary_leak_count-eq0-and[string]$DatasetManifest.revision-ceq'v01'-and[int]$DatasetManifest.overwritten_dataset_versions-eq0){0}else{1};judge_failure_count=if([bool]$Judge.thresholds_met-and[bool]$Judge.advisory_only-and[int]$Judge.annotation_count-eq100-and[int]$Judge.double_label_count-eq100-and[int]$Judge.rollout_decision_count+[int]$Judge.production_write_count-eq0){0}else{1};rollout_plan_failure_count=if([int]$Plan.gate_count-eq5-and[int]$Plan.risk_slice_count-eq5-and[int]$Plan.stop_rule_count-ge6-and-not[bool]$Plan.skip_gate_allowed-and[int]$Plan.minimum_nonoverlap_observation_hours-eq744-and[bool]$Plan.windows_must_be_nonoverlapping){0}else{1};cost_failure_count=if([int]$Cost.global.observed_attempt_count-gt0-and[int]$Cost.global.adopted_success_count-gt0-and$null-ne$Cost.global.total_attempt_cost_usd-and$null-ne$Cost.global.cost_per_adopted_success_usd-and[string]$Cost.budget.status-notmatch'^(?:blocked|pending)'){0}else{1};rollout_failure_count=if($RolloutValid){0}else{1};rollout_observation_31_day_failure_count=if([bool]$ObservationWindowState.passed){0}else{1}
