    $Postgres = Get-Content -LiteralPath (Join-Path $script:RepositoryRoot 'docs\execution\supply-chain\phase-boot\BOOT-005\isolated-postgres.json') -Raw -Encoding UTF8 | ConvertFrom-Json
    $Checks = [ordered]@{
