    'AGENTS.md',
    'execplan.md',
    'docs/execution/commands/',
    'docs/execution/schemas/',
    'docs/execution/evidence/boot/',
    'docs/execution/status/',
    'docs/execution/supply-chain/',
    'tool/bootstrap/'
  )
