    if ($Line.Length -lt 4) { continue }
    $PathValue = $Line.Substring(3).Replace('\', '/')
    $Allowed = $false
    foreach ($Prefix in $AllowedPrefixes) {
      if ($PathValue -ceq $Prefix -or $PathValue.StartsWith($Prefix, [StringComparison]::Ordinal)) { $Allowed = $true; break }
