    $SourceHashDrift = if (-not (Test-Path -LiteralPath $SourcePath -PathType Leaf)) { 1 } elseif ((Get-Sha256 -LiteralPath $SourcePath) -cne [string]$Manifest.source_record_sha256) { 1 } else { 0 }
