  }
  if ($TaskId -ceq 'TASK-P06-990') {
    $Projection=Get-P06LocalProjection;$RegressionPath=Join-Path $script:TaskEvidenceDirectory 'regression-summary.json';$RollbackPath=Join-Path $script:TaskEvidenceDirectory 'rollback-drill.json';$Regression=if(Test-Path -LiteralPath $RegressionPath){Get-Content -LiteralPath $RegressionPath -Raw -Encoding UTF8|ConvertFrom-Json}else{$null};$Rollback=if(Test-Path -LiteralPath $RollbackPath){Get-Content -LiteralPath $RollbackPath -Raw -Encoding UTF8|ConvertFrom-Json}else{$null}
